import { useMemo, useState, type FormEvent } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { SafeAreaTopScrim } from "@hatch/space-sdk/client";
import { Area, Bar, CartesianGrid, ComposedChart, Legend, Line, ReferenceLine, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { api, type ApiResponse } from "./api";

type Analysis = ApiResponse<typeof api, "analyzeInstrument">;
type OpenSignalSummary = ApiResponse<typeof api, "getOpenSignalSummary">;
type OpenSignalSummaryLoad = { summary: OpenSignalSummary; source: "live"|"cached"; cachedAt: string; fallbackReason: string|null };
type MarketBrief = ApiResponse<typeof api, "getMarketDayBrief">;
type MarketBriefLoad = { brief: MarketBrief; source: "live"|"cached"; cachedAt: string; fallbackReason: string|null };
type Tab = "MARKET"|"CROWD"|"DOSSIER"|"NEWS"|"SMART MONEY"|"SIGNAL TAPE"|"THEORIES"|"ENGINE HITS"|"WATCHLIST"|"ALERTS"|"JOURNAL";
const tabs: Tab[] = ["MARKET","CROWD","DOSSIER","NEWS","SMART MONEY","SIGNAL TAPE","THEORIES","ENGINE HITS","WATCHLIST","ALERTS","JOURNAL"];
const tabLabels: Record<Tab,string> = {"MARKET":"HOME","CROWD":"CROWD","DOSSIER":"DOSSIER","NEWS":"NEWS","SMART MONEY":"SMART MONEY","SIGNAL TAPE":"SIGNALS","THEORIES":"THEORIES","ENGINE HITS":"ENGINE HITS","WATCHLIST":"WATCHLIST","ALERTS":"ALERTS","JOURNAL":"JOURNAL"};
const money = (n:number|null|undefined,c="USD") => n==null?"—":new Intl.NumberFormat(undefined,{style:"currency",currency:c,maximumFractionDigits:n>=100?2:4}).format(n);
const quoteMoney = (n:number|null|undefined,c:string|null|undefined) => n==null?"—":c?money(n,c):`${num(n)} · currency unavailable`;
const num = (n:number|null|undefined,d=2) => n==null?"—":new Intl.NumberFormat(undefined,{maximumFractionDigits:d,notation:Math.abs(n)>=1_000_000?"compact":"standard"}).format(n);
const pct = (n:number|null|undefined) => n==null?"—":`${n>=0?"+":""}${num(n)}%`;
const dateLabel = (d:string) => { const parts=d.split("-").map(Number); const y=parts[0],m=parts[1],day=parts[2]; return y&&m&&day?new Intl.DateTimeFormat(undefined,{month:"short",day:"numeric"}).format(new Date(y,m-1,day)):d; };
const asOfLabel = (iso:string|null|undefined) => iso&&Number.isFinite(Date.parse(iso))?new Date(iso).toLocaleString():"timestamp unavailable";
const isStale = (iso:string|null|undefined) => !iso||!Number.isFinite(Date.parse(iso))||Date.now()-Date.parse(iso)>36*60*60*1000;
const sessionDateKey = (iso:string|null|undefined) => { const match=iso?.match(/^(\d{4}-\d{2}-\d{2})/); return match?.[1]??null; };
const regimeFreshness = (regimeAsOf:string|null|undefined,indexAsOf:Array<string|null|undefined>) => { const regimeSession=sessionDateKey(regimeAsOf); const currentSession=indexAsOf.map(sessionDateKey).filter((value):value is string=>value!=null).sort().at(-1)??null; return { stale:regimeSession==null||currentSession==null||regimeSession<currentSession, currentSession }; };
const directionLabel = (direction:"long"|"short"|"mixed") => direction==="long"?"LONG / bullish":direction==="short"?"SHORT / bearish":"MIXED / no directional edge";
const ratingBand = (score:number) => Math.abs(score)>=80?"80–100 alignment":Math.abs(score)>=65?"65–79 alignment":"0–64 alignment";
const OPEN_SIGNAL_CACHE_KEY = "equity-terminal-open-signals-v1";
const MARKET_BRIEF_CACHE_KEY = "equity-terminal-market-brief-v1";
function readOpenSignalCache(): OpenSignalSummaryLoad|null {
 try {
  const parsed=JSON.parse(localStorage.getItem(OPEN_SIGNAL_CACHE_KEY)??"null") as {summary?:OpenSignalSummary;cachedAt?:string}|null;
  return parsed?.summary&&typeof parsed.summary.generatedAt==="string"&&typeof parsed.cachedAt==="string"?{summary:parsed.summary,source:"cached",cachedAt:parsed.cachedAt,fallbackReason:null}:null;
 } catch { return null; }
}
function readMarketBriefCache(): MarketBriefLoad|null {
 try {
  const parsed=JSON.parse(localStorage.getItem(MARKET_BRIEF_CACHE_KEY)??"null") as {brief?:MarketBrief;cachedAt?:string}|null;
  return parsed?.brief&&typeof parsed.brief.generatedAt==="string"&&typeof parsed.cachedAt==="string"?{brief:parsed.brief,source:"cached",cachedAt:parsed.cachedAt,fallbackReason:null}:null;
 } catch { return null; }
}
// The isolated malfunction capture measured a 15.7 s cold artifact launch. The
// old 3.75 s client race expired before the server action could answer, even
// though the database read itself is fast. Budget for cold startup plus 25%
// headroom; after the first successful read, owned local cache renders at once.
const COLD_ARTIFACT_STARTUP_MS=16000;
const measuredReadTimeout=(p95Ms:number)=>Math.ceil(p95Ms*1.25/250)*250;
const HOME_SIGNAL_TIMEOUT_MS=measuredReadTimeout(COLD_ARTIFACT_STARTUP_MS);
const MARKET_BRIEF_TIMEOUT_MS=measuredReadTimeout(COLD_ARTIFACT_STARTUP_MS);
const timeoutSeconds=(milliseconds:number)=>num(milliseconds/1000,2);
async function loadOpenSignalSummary(): Promise<OpenSignalSummaryLoad> {
 const cached=readOpenSignalCache();
 let timeoutHandle:ReturnType<typeof setTimeout>|undefined;
 const live=api.getOpenSignalSummary({}).then((summary)=>{const cachedAt=new Date().toISOString();try{localStorage.setItem(OPEN_SIGNAL_CACHE_KEY,JSON.stringify({summary,cachedAt}))}catch{/* cache is optional */}return {summary,source:"live" as const,cachedAt,fallbackReason:null};}).catch((error:unknown)=>{if(cached)return {...cached,fallbackReason:`Refresh failed: ${String(error).replace(/^Error:\s*/,"")}`};throw error;});
 const timeout=new Promise<OpenSignalSummaryLoad>((resolve,reject)=>{timeoutHandle=setTimeout(()=>{if(cached)resolve({...cached,fallbackReason:`Cached signals shown after the ${timeoutSeconds(HOME_SIGNAL_TIMEOUT_MS)} second cold-start budget.`});else reject(new Error(`The signal ledger did not finish within ${timeoutSeconds(HOME_SIGNAL_TIMEOUT_MS)} seconds. Retry once the artifact server has started.`));},HOME_SIGNAL_TIMEOUT_MS)});
 try{return await Promise.race([live,timeout]);}finally{if(timeoutHandle)clearTimeout(timeoutHandle);}
}
async function loadMarketBriefWithTimeout(): Promise<MarketBriefLoad> {
 const cached=readMarketBriefCache();
 let timeoutHandle:ReturnType<typeof setTimeout>|undefined;
 const live=api.getMarketDayBrief({}).then((brief)=>{const cachedAt=new Date().toISOString();try{localStorage.setItem(MARKET_BRIEF_CACHE_KEY,JSON.stringify({brief,cachedAt}))}catch{/* cache is optional */}return {brief,source:"live" as const,cachedAt,fallbackReason:null};}).catch((error:unknown)=>{if(cached)return {...cached,fallbackReason:`Refresh failed: ${String(error).replace(/^Error:\s*/,"")}`};throw error;});
 const timeout=new Promise<MarketBriefLoad>((resolve,reject)=>{timeoutHandle=setTimeout(()=>{if(cached)resolve({...cached,fallbackReason:`Cached brief shown after the ${timeoutSeconds(MARKET_BRIEF_TIMEOUT_MS)} second cold-start budget.`});else reject(new Error(`Market data did not finish within ${timeoutSeconds(MARKET_BRIEF_TIMEOUT_MS)} seconds. No cached market brief is available yet.`));},MARKET_BRIEF_TIMEOUT_MS)});
 try{return await Promise.race([live,timeout]);}finally{if(timeoutHandle)clearTimeout(timeoutHandle);}
}

function Section({title,children,right}:{title:string;children:React.ReactNode;right?:React.ReactNode}){return <section className="section"><div className="section-head"><h3>{title}</h3>{right}</div>{children}</section>}
function MetricGrid({items}:{items:Array<{label:string;value:string;tone?:string}>}){return <div className="metric-grid">{items.map((x)=><div className="metric" key={x.label}><small>{x.label}</small><b className={x.tone??""}>{x.value}</b></div>)}</div>}
function LoadingSkeleton({label}:{label:string}){return <div className="skeleton" aria-label={label}><span/><span/><div><i/><i/><i/></div></div>}
type InstrumentSuggestion = ApiResponse<typeof api,"searchInstruments">["suggestions"][number];
function InstrumentAutocomplete({input,setInput,choose,loading,home=false}:{input:string;setInput:(value:string)=>void;choose:(value:string)=>void;loading:boolean;home?:boolean}){
 const [open,setOpen]=useState(false); const [message,setMessage]=useState<string|null>(null); const term=input.trim();
 const search=useQuery({queryKey:["instrument-search",term.toLowerCase()],queryFn:()=>api.searchInstruments({query:term}),enabled:open&&term.length>=2,staleTime:10*60*1000});
 const pick=(suggestion:InstrumentSuggestion)=>{setOpen(false);setMessage(null);choose(suggestion.symbol)};
 const submit=async(event:FormEvent)=>{event.preventDefault();if(term.length<2)return;setOpen(true);setMessage(null);const result=await search.refetch();const suggestions=result.data?.suggestions??[];setMessage(suggestions.length?"Pick the exact listing below.":result.data?.note??"No listed instrument matched. Try a ticker or a more specific company name.")};
 return <form className={home?"home-search":"searchrow"} onSubmit={submit}><select aria-label={home?"Quick asset picker":"Asset picker"} value="" onChange={event=>event.target.value&&choose(event.target.value)}><option value="">{home?"QUICK PICK":"ASSET PICKER"}</option><option value="SPY">SPY · S&amp;P 500</option><option value="QQQ">QQQ · Nasdaq 100</option><option value="TLT">TLT · Treasuries</option><option value="GLD">GLD · Gold</option><option value="BTC-USD">BTC · Bitcoin</option></select><div className="instrument-typeahead"><input aria-label={home?"Ticker or company name":"Ticker or company"} value={input} onFocus={()=>setOpen(true)} onChange={event=>{setInput(event.target.value);setOpen(true);setMessage(null)}} autoComplete="off" aria-expanded={open&&!!search.data?.suggestions.length} aria-controls={home?"home-instrument-suggestions":"nav-instrument-suggestions"} placeholder={home?"Ticker or company name":"Ticker or company"}/>{open&&term.length>=2&&<div id={home?"home-instrument-suggestions":"nav-instrument-suggestions"} className="instrument-suggestions" role="listbox" aria-label="Matching listed instruments">{search.isFetching&&<div className="suggestion-state">SEARCHING YAHOO FINANCE…</div>}{!search.isFetching&&search.data?.suggestions.map(item=><button type="button" role="option" key={`${item.symbol}-${item.exchange}`} onMouseDown={event=>event.preventDefault()} onClick={()=>pick(item)}><span><b>{item.name}</b><small>{item.quoteType}</small></span><strong>{item.symbol}<small>{item.exchange} · {item.country}</small></strong></button>)}{!search.isFetching&&search.data?.note&&<div className="suggestion-state">{search.data.note}</div>}{message&&<div className="suggestion-state pick-required">{message}</div>}</div>}</div><button type="submit" disabled={term.length<2||loading||search.isFetching}>{search.isFetching?"SEARCHING…":loading?home?"ANALYZING…":"SCAN…":"FIND"}</button></form>
}
function Reliability({score}:{score:number}){const q=useQuery({queryKey:["tracker"],queryFn:()=>api.getSignalTracker({}),staleTime:5*60*1000});const band=ratingBand(score);const rows=q.data?.stats.filter(row=>row.agreementBand===band)??[];const samples=rows.reduce((sum,row)=>sum+row.samples,0);const hits=rows.reduce((sum,row)=>sum+row.hits,0);const grossAverage=samples?rows.reduce((sum,row)=>sum+row.avgReturn*row.samples,0)/samples:null;return <div className="reliability"><b>Fixed 30-session direction record · {band}</b>{q.isPending?<span>Loading accepted evaluations…</span>:samples?<span className={(grossAverage??0)>=0?"pos":"neg"}>{pct(grossAverage)} average gross return · {num(hits/samples*100)}% directional hits · {hits}/{samples} resolved · costs unknown</span>:<span>UNCALIBRATED · no resolved evaluations in this exact cohort</span>}</div>}
function TerminalNav({tab,switchTab,className=""}:{tab:Tab;switchTab:(tab:Tab)=>void;className?:string}){return <nav className={`tabs ${className}`.trim()} aria-label="Terminal sections">{tabs.map(t=><button key={t} className={tab===t?"active":""} onClick={()=>switchTab(t)}>{tabLabels[t]}</button>)}</nav>}

function ageLabel(seconds:number|null){if(seconds==null)return "age unavailable";if(seconds<60)return `${seconds}s old`;if(seconds<3600)return `${Math.floor(seconds/60)}m old`;if(seconds<86400)return `${Math.floor(seconds/3600)}h old`;return `${Math.floor(seconds/86400)}d old`;}
function clockSkewLabel(eventAt:string|null,receivedAt:string|null){if(!eventAt||!receivedAt)return "";const skew=Math.round((Date.parse(eventAt)-Date.parse(receivedAt))/1000);return Number.isFinite(skew)&&skew>1?` · PROVIDER CLOCK +${skew}s VS RECEIPT`:"";}
function ageFromIso(iso:string|null|undefined){return iso&&Number.isFinite(Date.parse(iso))?Math.max(0,Math.floor((Date.now()-Date.parse(iso))/1000)):null;}
function MarketFreshness({symbol}:{symbol:string}){
 const qc=useQueryClient(); const q=useQuery({queryKey:["market-freshness",symbol],queryFn:()=>api.getMarketFreshness({symbol}),staleTime:60*1000}); const refresh=useMutation({mutationFn:()=>api.refreshMarketData({symbols:[symbol],trigger:"manual"}),onSuccess:()=>qc.invalidateQueries({queryKey:["market-freshness",symbol]})}); const row=q.data?.symbols[0];
 return <section className="freshness-panel" aria-label={`${symbol} market data freshness`}><header><div><span className="eyebrow">INDEPENDENT MARKET-DATA LANE</span><h2>Inputs &amp; timestamps</h2></div><button className="secondary" onClick={()=>refresh.mutate()} disabled={refresh.isPending}>{refresh.isPending?"REFRESHING…":"REFRESH MARKET DATA"}</button></header><p className="freshness-intro">Price, chart and volume refresh separately from the expensive dossier. The public feed may be delayed; fresh means current against its own timestamp threshold, not exchange real-time.</p>{refresh.error&&<div className="error">Refresh failed: {String(refresh.error)}</div>}{refresh.data&&<div className={`market-load-status ${refresh.data.status}`} role="status"><b>{refresh.data.status.toUpperCase()}</b><span>{refresh.data.symbols[0]?.observationsWritten??0} observations written · {refresh.data.symbols[0]?.observationsReused??0} deduplicated · {refresh.data.symbols[0]?.statusEventsAppended??0} status events</span></div>}{q.isPending?<LoadingSkeleton label="Loading input freshness"/>:row?<><div className="freshness-grid">{row.inputs.map(input=><article key={input.kind} className={input.stale||input.state==="error"?"stale":""}><div><span className={`status ${input.state}`}>{input.state.replace("_"," ")}</span><small>{input.candleState}</small></div><b>{input.label}</b><strong>{input.value==null?"—":num(input.value,4)}</strong><dl><div><dt>EVENT</dt><dd>{asOfLabel(input.eventAt)}</dd></div><div><dt>RECEIVED</dt><dd>{asOfLabel(input.receivedAt)}</dd></div><div><dt>PROVIDER AGE</dt><dd>{ageLabel(input.providerAgeSeconds)}</dd></div><div><dt>FETCH HEALTH</dt><dd>{ageLabel(input.fetchAgeSeconds)} since success</dd></div>{input.volume!=null&&<div><dt>OHLCV</dt><dd>{num(input.open,4)} / {num(input.high,4)} / {num(input.low,4)} / {num(input.close,4)} · vol {num(input.volume)}</dd></div>}<div><dt>SOURCE</dt><dd>{input.source} · {input.venue}</dd></div></dl>{clockSkewLabel(input.eventAt,input.receivedAt)&&<small>{clockSkewLabel(input.eventAt,input.receivedAt).replace(/^ · /,"")}</small>}<p>{input.entitlement}</p><details><summary>RAW → DISPLAYED TRACE</summary><code>{input.trace}</code></details>{input.error&&<span className="neg">{input.error}</span>}</article>)}</div>{row.statusEvents.length>0&&<details className="freshness-events"><summary>APPENDED STATUS EVENTS · {row.statusEvents.length}</summary>{row.statusEvents.map((event,index)=><div key={`${event.signalId}-${event.status}-${event.observedAt}-${index}`}><b>{event.status.replaceAll("_"," ")}</b><span>Signal {event.signalId} · {asOfLabel(event.observedAt)} · {event.settlement}</span><p>{event.note}</p></div>)}</details>}<small className="freshness-note">{q.data?.note}</small></>:<div className="empty"><b>No market observation has been stored for {symbol}.</b><span>Refresh market data to create the first append-only observation.</span></div>}</section>;
}

function AtGlanceVerdict({a,tab,setTab,onWatch,watching,onTrack,tracking,trackNote}:{a:Analysis;tab:Tab;setTab:(tab:Tab)=>void;onWatch:()=>void;watching:boolean;onTrack:()=>void;tracking:boolean;trackNote:string|null}){
 const instrument=a.instrument;
 const live=useQuery({queryKey:["market-freshness",instrument?.symbol],queryFn:()=>api.getMarketFreshness({symbol:instrument?.symbol??""}),enabled:!!instrument?.symbol,staleTime:30*1000});
 const liveInputs=live.data?.symbols[0]?.inputs??[]; const liveQuote=liveInputs.find(input=>input.kind==="quote"); const liveCandle=liveInputs.find(input=>input.kind==="forming_candle")??liveInputs.find(input=>input.kind==="completed_candle"); const currentPrice=liveQuote&&!liveQuote.stale&&liveQuote.value!=null?liveQuote.value:instrument?.price??null;
 const score=a.factorModel?.score;
 const direction=a.factorModel?.direction??a.levels?.direction??(score!=null&&score<0?"short":"long");
 const walkForwardObservations=a.walkForward?.observations??0;
 const walkForwardStatus=a.walkForward?.qualified?"SAMPLE SUFFICIENT":"THIN SAMPLE";
 if(!instrument)return null;
 return <section className={`verdict-board ${direction}`} aria-label={`${instrument.symbol} directional factor agreement`}>
  <div className="verdict-lead">
   <div className="verdict-identity"><span className="eyebrow">{instrument.symbol} · {instrument.name}</span><div className="price"><strong>{quoteMoney(currentPrice,instrument.currency)}</strong><span className={(instrument.changePercent??0)>=0?"pos":"neg"}>{pct(instrument.changePercent)}</span></div><small>{liveQuote&&!liveQuote.stale?`CURRENT MARK · ${liveQuote.source} · event ${asOfLabel(liveQuote.eventAt)}`:`ANALYSIS MARK · as of ${asOfLabel(instrument.asOf)}`}{liveCandle?.volume!=null?` · DAILY VOLUME ${num(liveCandle.volume)} ${liveCandle.quoteCurrency??instrument.currency??"currency unavailable"} · ${liveCandle.venue}`:""}</small></div>
   <div className="verdict-call"><small>FACTOR AGREEMENT · NOT A PROBABILITY</small><strong>{direction.toUpperCase()}</strong><span>{score==null?"NO SCORE":`${score>0?"+":""}${score} / 100`}</span></div>
   <div className="verdict-confidence"><small>LEGACY TREND BASELINE · NOT LIVE VALIDATION</small><b>{walkForwardStatus}</b><span>{walkForwardObservations} replay observations{a.walkForward?.qualified&&a.walkForward.hitRate!=null&&a.walkForward.averageDirectionalReturn!=null?` · ${num(a.walkForward.hitRate)}% directional hit · ${pct(a.walkForward.averageDirectionalReturn)} avg return · edge not validated`:` · fewer than 20 baseline observations`}</span></div>
  </div>
  <div className="verdict-levels">
   <div><small>ENTRY ZONE</small><b>{a.levels?`${quoteMoney(a.levels.entryLow,instrument.currency)}–${quoteMoney(a.levels.entryHigh,instrument.currency)}`:"Unavailable"}</b></div>
   <div><small>INVALIDATION</small><b className="neg">{quoteMoney(a.levels?.invalidation,instrument.currency)}</b>{a.levels&&<span>{num(a.levels.invalidationAtrMultiple,2)}× Wilder ATR-14 · ATR {quoteMoney(a.levels.atr14,instrument.currency)}</span>}</div>
   <div><small>TARGET 1 (CHART)</small><b>{quoteMoney(a.levels?.target1,instrument.currency)}</b></div>
   <div><small>TARGET 2 (CHART)</small><b>{quoteMoney(a.levels?.target2,instrument.currency)}</b></div>
  </div>
  <div className="verdict-thesis"><small>THESIS</small><p>{a.thesis??"Thesis unavailable for this fetch."}</p></div>
  <div className="verdict-kill"><small>WHAT KILLS IT</small><p>{a.failure??"No validated invalidation tripwire is available."}</p><span>DISCONFIRMING EVIDENCE · n={a.factorModel?.factors.filter(factor=>factor.score<0).length??0}</span>{a.factorModel&&a.factorModel.factors.some(factor=>factor.quality!=="GOOD")&&<span>KNOWN GAPS · {a.factorModel.factors.filter(factor=>factor.quality!=="GOOD").map(factor=>factor.name).join(", ")}</span>}</div>
  {score!=null&&<Reliability score={score}/>} 
  <div className="verdict-foot"><span className={isStale(instrument.asOf)?"stale":"fresh"}>{isStale(instrument.asOf)?"STALE":"FRESH"}</span><span>Source event {asOfLabel(instrument.asOf)} · observation age {ageLabel(ageFromIso(instrument.asOf))} · cache receipt unavailable</span><span>Factor agreement, not profit probability</span><button className="secondary compact" onClick={onWatch} disabled={watching}>{watching?"ADDING…":"+ WATCH"}</button><button className="secondary compact" onClick={onTrack} disabled={tracking||a.factorModel?.direction==="mixed"}>{tracking?"TRACKING…":"TRACK THIS"}</button></div>{trackNote&&<div className="notice">{trackNote}</div>}
  {a.factorModel&&<details className="verdict-ledger"><summary>WHY · FACTOR LEDGER</summary><div className="notice formula"><b>Freshness:</b> {a.factorModel.freshness}</div>{a.levels&&<div className="notice formula"><b>Invalidation basis:</b> {a.levels.invalidationBasis}. Wilder ATR-14 = {quoteMoney(a.levels.atr14,instrument.currency)}; applies symmetrically to long and short setups.</div>}<div className="factor-table" role="table" aria-label={`${instrument.symbol} factor ledger`}><div className="factor-row factor-head" role="row"><span>Factor</span><span>Weight</span><span>Score</span><span>Contribution</span></div>{a.factorModel.factors.map(factor=>{const seconds=ageFromIso(factor.asOf);const stale=seconds==null||seconds>86400;return <div className={`factor-row ${factor.quality.toLowerCase()}`} role="row" key={factor.name}><span><b>{factor.name}</b><small>{factor.reading}</small><small>{factor.source} · event {asOfLabel(factor.asOf)} · observation age {ageLabel(seconds)} · cache receipt unavailable · {stale?"STALE":"FRESH"} · {factor.quality}</small>{factor.quality!=="GOOD"&&<small>{factor.qualityReason}</small>}</span><span>{factor.weight}</span><span className={factor.score>0?"pos":factor.score<0?"neg":""}>{factor.score>0?"+":""}{factor.score}</span><span>{factor.contribution>0?"+":""}{factor.contribution}</span></div>})}</div><div className="notice formula"><b>Formula:</b> {a.factorModel.formula}</div></details>}
  <nav className="instrument-actions" aria-label={`${instrument.symbol} analysis views`}>{(["DOSSIER","SIGNAL TAPE","SMART MONEY","WATCHLIST"] as const).map(view=><button key={view} className={tab===view?"active":""} onClick={()=>setTab(view)}>{view==="WATCHLIST"?"ENTRY CHECK":view==="SIGNAL TAPE"?"SIGNALS":view}</button>)}</nav>
 </section>
}

export function App(){
 const qc=useQueryClient();
 const initialSymbol=useMemo(()=>new URLSearchParams(window.location.search).get("symbol")?.trim()??"",[]);
 const [tab,setTab]=useState<Tab>(initialSymbol?"DOSSIER":"MARKET");
 const [input,setInput]=useState(initialSymbol);
 const [query,setQuery]=useState(initialSymbol);
 const [chartMode,setChartMode]=useState<"line"|"candles">("line");
 const [recent,setRecent]=useState<string[]>(()=>{try{return JSON.parse(localStorage.getItem("equity-terminal-recent")??"[]") as string[]}catch{return []}});
 const analysis=useQuery({queryKey:["analysis",query],queryFn:()=>api.analyzeInstrument({symbol:query}),enabled:query.length>0,staleTime:5*60*1000});
 const a=analysis.data;
 const addWatch=useMutation({mutationFn:()=>api.addWatch({query:a?.instrument?.symbol??query}),onSuccess:()=>qc.invalidateQueries({queryKey:["watchlist"]})});
 const trackSignal=useMutation({mutationFn:()=>api.trackAnalyzedSignal({query:a?.instrument?.symbol??query}),onSuccess:()=>{qc.invalidateQueries({queryKey:["tracker"]});qc.invalidateQueries({queryKey:["radar"]})}});
 const setSymbolUrl=(symbol:string)=>{const params=new URLSearchParams(window.location.search);params.set("symbol",symbol.toUpperCase());window.history.replaceState({},"",`${window.location.pathname}?${params.toString()}`)};
 const choose=(value:string)=>{const symbol=value.trim();if(!symbol)return;setRecent(items=>{const next=[symbol,...items.filter(item=>item.toUpperCase()!==symbol.toUpperCase())].slice(0,5);localStorage.setItem("equity-terminal-recent",JSON.stringify(next));return next});setInput(symbol);setQuery(symbol);setSymbolUrl(symbol);setTab("DOSSIER")};
 const openTape=(value:string)=>{const symbol=value.trim();if(!symbol)return;setInput(symbol);setQuery(symbol);setSymbolUrl(symbol);setTab("SIGNAL TAPE")};
 const switchTab=(next:Tab)=>setTab(next);
 const instrumentTab=tab==="DOSSIER"||tab==="SIGNAL TAPE"||tab==="SMART MONEY"||tab==="WATCHLIST";
 return <div className="app"><SafeAreaTopScrim backgroundColor="var(--bg)"/><main className="shell">
  <div className={`searchbar ${tab==="MARKET"?"market-searchbar":""}`}>{tab!=="MARKET"&&tab!=="CROWD"&&<div className="query-builder"><InstrumentAutocomplete input={input} setInput={setInput} choose={choose} loading={analysis.isFetching}/></div>}<TerminalNav tab={tab} switchTab={switchTab} className={tab==="MARKET"?"market-nav-top":""}/></div>
  {tab==="MARKET"&&<><MarketLanding choose={choose} openTape={openTape} openTab={setTab} input={input} setInput={setInput} recent={recent} loading={analysis.isFetching}/><TerminalNav tab={tab} switchTab={switchTab} className="market-nav-mobile"/></>} 
  {tab==="CROWD"&&<Crowd/>}
  {tab==="NEWS"&&<News symbol={a?.instrument?.symbol??query} qc={qc}/>} 
  {tab==="WATCHLIST"&&<Watchlist choose={choose} qc={qc}/>} {tab==="THEORIES"&&<Theories qc={qc} choose={choose}/>} {tab==="ENGINE HITS"&&<EngineHits/>} {tab==="ALERTS"&&<Alerts qc={qc} choose={choose}/>} {tab==="JOURNAL"&&<><Journal symbol={a?.instrument?.symbol??query} qc={qc} choose={choose}/><Rules qc={qc}/></>} 
  {instrumentTab&&(query?analysis.isPending?<LoadingSkeleton label="Loading market evidence"/>:analysis.error?<div className="error">Analysis failed: {String(analysis.error)}</div>:a?.status==="error"?<div className="error">{a.error}</div>:a?.status==="private"&&a.privateCompany?<PrivatePanel data={a.privateCompany} choose={choose}/>:<>
   {a?.instrument&&<><AtGlanceVerdict a={a} tab={tab} setTab={setTab} onWatch={()=>addWatch.mutate()} watching={addWatch.isPending} onTrack={()=>trackSignal.mutate()} tracking={trackSignal.isPending} trackNote={trackSignal.data?.note??null}/><MarketFreshness symbol={a.instrument.symbol}/>{tab==="DOSSIER"&&<><DossierSynthesis a={a}/><ValuationBlock key={a.instrument.symbol} symbol={a.instrument.symbol} initialData={a.valuation}/></>} {a.commodity&&<div className="notice instrument-note"><b>Plotted: {a.instrument.symbol}.</b> {a.commodity.why}</div>}{a.instrument.resolutionMethod==="symbol_search"&&<div className="matchline instrument-note">Resolved from “{a.instrument.resolvedFrom}” via Yahoo Finance symbol/name search.</div>}{addWatch.data?.error&&<div className="error instrument-note">{addWatch.data.error}</div>}</>}
   {tab==="SIGNAL TAPE"&&<SignalTape query={query} openDossier={()=>setTab("DOSSIER")}/>} {tab==="DOSSIER"&&a&&<><Dossier a={a} mode={chartMode} setMode={setChartMode}/>{a.instrument&&<Research a={a}/>}</>} {tab==="SMART MONEY"&&a&&<SmartMoney a={a}/>} {tab==="WATCHLIST"&&<Sizing key={a?.instrument?.symbol??query} symbol={a?.instrument?.symbol??query} price={a?.instrument?.price??0} invalidation={a?.levels?.invalidation??0} volatility={(()=>{const atr=a?.indicators.find(x=>x.label==="ATR 14")?.value,px=a?.instrument?.price;return atr&&px?atr/px>=.06?"high":atr/px>=.03?"elevated":"normal":"unavailable"})()}/>} 
  </>:tab==="SMART MONEY"?<MarketSmartMoney openTab={setTab}/>:<InstrumentPrompt onFocus={()=>document.querySelector<HTMLInputElement>('.searchrow input')?.focus()}/>)}
  {tab==="SIGNAL TAPE"&&<><Scorecard/><Radar choose={choose} openTape={openTape}/><AutoScan choose={choose} openTape={openTape} qc={qc}/><Tracker openTape={openTape}/><Alerts qc={qc} choose={choose}/></>} 
 </main></div>
}

function MarketLanding({choose,openTape,openTab,input,setInput,recent,loading}:{choose:(q:string)=>void;openTape:(q:string)=>void;openTab:(tab:Tab)=>void;input:string;setInput:(value:string)=>void;recent:string[];loading:boolean}){
 const [view,setView]=useState<"signals"|"trending">("signals");
 return <div className="market-landing">
  <div className="home-view-tabs" role="tablist" aria-label="Home view"><button role="tab" aria-selected={view==="signals"} className={view==="signals"?"active":""} onClick={()=>setView("signals")}><b>SIGNALS</b><span>Fast tracked calls</span></button><button role="tab" aria-selected={view==="trending"} className={view==="trending"?"active":""} onClick={()=>setView("trending")}><b>TRENDING</b><span>Runners · sectors · breadth</span></button></div>
  {view==="signals"?<SignalLanding openTape={openTape} openTab={openTab}/>:<MarketHome choose={choose} openTab={openTab}/>}
  <HomePicker input={input} setInput={setInput} choose={choose} recent={recent} loading={loading}/>
 </div>;
}

function SignalLanding({openTape,openTab}:{openTape:(q:string)=>void;openTab:(tab:Tab)=>void}){
 const initialCache=useMemo(()=>readOpenSignalCache(),[]);
 const q=useQuery({queryKey:["open-signal-summary-bounded"],queryFn:loadOpenSignalSummary,staleTime:60*1000,initialData:initialCache??undefined,initialDataUpdatedAt:initialCache?0:undefined,retry:false});
 const freshness=useQuery({queryKey:["market-freshness-all"],queryFn:()=>api.getMarketFreshness({}),staleTime:60*1000,retry:false});
 const loaded=q.data; const data=loaded?.summary; const currentInput=(symbol:string)=>freshness.data?.symbols.find(row=>row.symbol===symbol)?.inputs.find(input=>input.kind==="quote");
 return <section className="signal-landing" aria-label="Open tracked signals">
  <header><div><span className="eyebrow">LEGACY SIGNAL LEDGER · OPEN CALLS</span><h1>{data?`${data.signals.length} legacy tracked ${data.signals.length===1?"signal":"signals"} in motion`:"Open legacy signals"}</h1><p>Preserved historical calls load first. Formal Phase 1.2 cohort reporting is in full Signals.</p></div><button className="secondary" onClick={()=>openTab("SIGNAL TAPE")}>OPEN FULL SIGNALS</button></header>
  {loaded&&<div className={`market-load-status ${loaded.source}`} role="status"><b>{loaded.source==="cached"?"CACHED SIGNAL LEDGER":"SIGNAL LEDGER UPDATED"}</b><span>{loaded.source==="cached"?`Saved ${asOfLabel(loaded.cachedAt)}`:`Read ${asOfLabel(data?.generatedAt)}`}</span>{loaded.fallbackReason&&<small>{loaded.fallbackReason}</small>}{q.isFetching&&<small>Checking for newer signal marks in the background…</small>}</div>}
  {q.isPending?<div className="signal-start"><span className="loading-dot"/><span><b>STARTING SIGNAL LEDGER…</b><small>Cold starts can take up to {timeoutSeconds(HOME_SIGNAL_TIMEOUT_MS)} seconds. The rest of the home stays usable.</small></span></div>:q.error?<div className="signal-load-failure"><div className="error">{String(q.error).replace(/^Error:\s*/,"")}</div><button className="action" onClick={()=>void q.refetch()}>RETRY SIGNALS</button></div>:data&&data.signals.length?<div className="landing-signal-list">{data.signals.map(signal=>{const live=currentInput(signal.symbol);const mark=live?.value??signal.currentPrice;const returnPct=mark==null?signal.returnPct:(signal.direction==="long"?(mark-signal.entryPrice)/signal.entryPrice:(signal.entryPrice-mark)/signal.entryPrice)*100;return <button key={signal.id} onClick={()=>openTape(signal.symbol)} aria-label={`Open ${signal.symbol} signal tape`}><div className="landing-signal-id"><span className={`signal-direction ${signal.direction}`}>{signal.direction}</span><b>{signal.symbol}</b><small>{signal.name}</small></div><strong className={(returnPct??0)>=0?"pos":"neg"}>{returnPct==null?"NO MARK":pct(returnPct)}</strong><div className="landing-signal-levels"><span><small>ISSUED ENTRY</small>{money(signal.entryPrice)}</span><span><small>CURRENT MARK</small>{money(mark)}</span><span><small>ISSUED INVALIDATION</small>{money(signal.invalidationLevel)}</span><span><small>ISSUED TARGET 1</small>{money(signal.target1)}</span></div><footer><span>OPEN {signal.daysOpen}D · {dateLabel(signal.signalDate)}</span><span className={live?.stale||live?.state==="error"?"stale":"fresh"}>{live?`${live.state.replace("_"," ").toUpperCase()} · EVENT ${asOfLabel(live.eventAt)} · RECEIVED ${asOfLabel(live.receivedAt)} · CACHE ${ageLabel(live.cacheAgeSeconds)}${clockSkewLabel(live.eventAt,live.receivedAt)}`:`LEGACY MARK · ${isStale(signal.sourceAsOf)?"STALE":"CURRENT"} · EVENT ${asOfLabel(signal.sourceAsOf)} · OBSERVATION AGE ${ageLabel(ageFromIso(signal.sourceAsOf))} · RECEIPT/CACHE AGE UNAVAILABLE`}</span></footer></button>})}</div>:data?<div className="empty signal-landing-empty"><b>No open tracked signals.</b><span>The ledger is clear. Open Signals to run discovery or inspect completed calls.</span><button onClick={()=>openTab("SIGNAL TAPE")}>OPEN SIGNALS</button></div>:null}
  {data?.latestBrief&&<div className="signal-ledger-brief"><b>PHASE 1.2 COHORT POST-MORTEM · {dateLabel(data.latestBrief.capturedDay)}</b><span>{data.latestBrief.summary}</span></div>}
  {data&&<small className="landing-asof">Ledger read {asOfLabel(data.generatedAt)} · database only; no market refresh was started.</small>}
 </section>;
}

function HomePicker({input,setInput,choose,recent,loading}:{input:string;setInput:(value:string)=>void;choose:(value:string)=>void;recent:string[];loading:boolean}){
 return <section className="home-picker" aria-label="Analyze an asset"><div><span className="eyebrow">START A DOSSIER</span><h2>What do you want to understand?</h2></div><InstrumentAutocomplete input={input} setInput={setInput} choose={choose} loading={loading} home/><div className="home-recents"><b>RECENT PICKS</b>{recent.length?<div>{recent.map(item=><button key={item} onClick={()=>choose(item)}>{item}</button>)}</div>:<span>Your analyzed names will stay here on this device.</span>}</div></section>
}

type CrowdSearch = ApiResponse<typeof api,"searchCrowdMarkets">;
type CrowdOption = CrowdSearch["options"][number];
function Crowd(){
 const [input,setInput]=useState(""); const [query,setQuery]=useState(""); const [selected,setSelected]=useState<CrowdOption|null>(null);
 const search=useQuery({queryKey:["crowd-search",query],queryFn:()=>api.searchCrowdMarkets({query}),enabled:query.length>=2,staleTime:15*60*1000});
 const research=useMutation({mutationFn:(market:CrowdOption)=>api.researchCrowdMarket({query,slug:market.slug})});
 const submit=(event:FormEvent)=>{event.preventDefault();const next=input.trim();if(next.length<2)return;setSelected(null);research.reset();setQuery(next)};
 const select=(market:CrowdOption)=>{setSelected(market);research.mutate(market)}; const result=research.data;
 return <section className="crowd-page"><header><span className="eyebrow">POLYMARKET</span><h1>Crowd price vs measured base rate</h1><p>Search in plain words, pick the exact market, then compare its Yes price with a horizon-matched historical read.</p></header><form className="crowd-search" onSubmit={submit}><input aria-label="Search Polymarket markets" value={input} onChange={event=>setInput(event.target.value)} placeholder="BTC 90000 in 4 days"/><button disabled={input.trim().length<2||search.isFetching}>{search.isFetching?"SEARCHING…":"SEARCH"}</button></form>
  {search.error&&<div className="error">Market search failed: {String(search.error)}</div>}{search.data?.state==="no_data"&&<div className="empty">{search.data.reason}</div>}
  {search.data?.options.length?<div className="crowd-options" aria-label="Matching Polymarket options"><div className="section-head"><h3>SELECT A MARKET</h3><span>{search.data.options.length} MATCHES · {asOfLabel(search.data.asOf)}</span></div>{search.data.options.map(option=><button key={option.slug} className={selected?.slug===option.slug?"active":""} onClick={()=>select(option)}><span><b>{option.question}</b>{option.eventTitle&&option.eventTitle!==option.question?<small>{option.eventTitle}</small>:null}</span><strong>{num(option.yesImpliedCrowdPrice*100,1)}% YES<small>{money(option.volume24hr)} 24H VOL</small></strong></button>)}</div>:null}
  {research.isPending&&<LoadingSkeleton label="Researching selected market"/>}{research.error&&<div className="error">Research failed: {String(research.error)}</div>}{result&&<article className={`crowd-verdict ${result.state}`}><div className="section-head"><h3>RESEARCHED VERDICT</h3><span>{result.state==="available"?"MEASURED":"PROBABILITY WITHHELD"}</span></div><h2>{result.market?.question}</h2><div className="crowd-comparison"><div><small>CROWD IMPLIED</small><b>{result.crowdProbability==null?"—":`${num(result.crowdProbability,1)}%`}</b><span>Polymarket Yes price · {result.market?asOfLabel(result.market.asOf):"timestamp unavailable"}</span></div><div><small>TERMINAL READ</small><b>{result.researchedProbability==null?"WITHHELD":`${num(result.researchedProbability,1)}%`}</b><span>{result.researchedProbability==null?result.reason:`Empirical base rate · N=${result.sampleSize}`}</span></div><div><small>POTENTIAL EDGE</small><b className={(result.edgePoints??0)>0?"pos":(result.edgePoints??0)<0?"neg":""}>{result.edgePoints==null?"—":`${result.edgePoints>0?"+":""}${num(result.edgePoints,1)} pts`}</b><span>Terminal minus crowd · not a trade signal</span></div></div><div className="crowd-basis"><b>BASIS</b><p>{result.basis}</p>{result.factorAgreement&&<span>Current factor agreement {result.factorAgreement.score>0?"+":""}{result.factorAgreement.score} · {result.factorAgreement.direction} · comparison band {result.factorAgreement.band}{result.instrument?` · ${result.instrument.symbol} ${money(result.instrument.price)}`:""}</span>}</div>{result.market&&<a className="secondary crowd-source" href={result.market.marketUrl} target="_blank" rel="noreferrer">OPEN SELECTED MARKET</a>}</article>}
 </section>
}

function InstrumentPrompt({onFocus}:{onFocus:()=>void}){return <div className="instrument-prompt"><span className="eyebrow">INSTRUMENT VIEW</span><h2>Choose what to analyze.</h2><p>Search a ticker, company, private company, or commodity above to open its dossier and market evidence.</p><button className="action" onClick={onFocus}>SEARCH INSTRUMENTS</button></div>}

type StockValuation = ApiResponse<typeof api,"valuestock">;
function ValuationBlock({symbol,initialData}:{symbol:string;initialData:StockValuation|null}){
 const run=useMutation({mutationFn:()=>api.valuestock({symbol})});
 const data=run.data??initialData;
 return <section className="valuation-block" aria-label={`${symbol} equity valuation`}>
  <header className="valuation-head"><div><h2>Equity valuation</h2><p>Loaded with the dossier. Cash flows, dilution, multiples and operating evidence; no price target.</p></div><button className="action" onClick={()=>run.mutate()} disabled={run.isPending}>{run.isPending?"REFRESHING…":"REFRESH"}</button></header>
  {!data&&!run.isPending&&!run.error&&<div className="valuation-empty"><b>VALUATION UNAVAILABLE</b><span>The free fundamentals layer returned no usable result.</span></div>}
  {run.isPending&&<LoadingSkeleton label={`Refreshing ${symbol} valuation`}/>} {run.error&&<div className="error">Valuation refresh failed: {String(run.error)}</div>}
  {data&&<ValuationResult data={data}/>} 
 </section>
}
function ValuationResult({data}:{data:StockValuation}){
 const sourceById=new Map(data.sources.map(source=>[source.id,source]));
 const sourceLinks=(ids:string[])=><span className="valuation-cites">{ids.map(id=>{const source=sourceById.get(id);if(!source)return null;return source.url?<a key={id} href={source.url} target="_blank" rel="noreferrer">{id}</a>:<span key={id}>{id}</span>})}</span>;
 return <div className="valuation-result">
  <div className="valuation-status"><span className={`status ${data.status==="ok"?"confirming":data.status==="partial"?"contested":"challenged"}`}>{data.status}</span><b>{data.symbol} · as of {asOfLabel(data.asOf)}</b><span>{data.note}</span></div>
  {data.refresh.state!=="not_needed"&&<div className={`valuation-refresh ${data.refresh.state}`}><b>KEYED CROSS-CHECK · {data.refresh.state.toUpperCase()}</b><span>{data.refresh.note}</span></div>}
  <div className="valuation-sections">{data.sections.map(section=><details key={section.number} className="valuation-section" open={section.number===1||section.number===4||section.number===8}><summary><span>{String(section.number).padStart(2,"0")}</span><b>{section.title}</b><em className={section.verdict==="cheap"||section.verdict==="supportive"?"pos":section.verdict==="rich"||section.verdict==="caution"?"neg":""}>{section.verdict}</em></summary><div className="valuation-section-body"><p>{section.summary}</p>{section.metrics.length>0&&<div className="valuation-metrics">{section.metrics.map(metric=><div className={`valuation-metric ${metric.status}`} key={metric.label}><small>{metric.label}</small><strong>{metric.value}</strong><span>{metric.detail} {sourceLinks(metric.sourceIds)}</span></div>)}</div>}{section.evidence.length>0&&<ul className="valuation-evidence">{section.evidence.map((item,index)=><li key={index}>{item.text} {sourceLinks(item.sourceIds)}</li>)}</ul>}</div></details>)}</div>
  <details className="valuation-method"><summary>Method + sources</summary><div><ul>{data.assumptions.map(item=><li key={item}>{item}</li>)}</ul><ol>{data.sources.map(source=><li key={source.id}><b>{source.id}</b> · {source.url?<a href={source.url} target="_blank" rel="noreferrer">{source.label}</a>:source.label} · as of {source.asOf}</li>)}</ol></div></details>
 </div>
}

function DossierSynthesis({a}:{a:Analysis}){
 const synthesis=a.synthesis,sections=a.sectionVerdicts;if(!synthesis||!sections)return null;
 const rows=[{label:"CHART",...sections.chart},{label:"VALUATION",...sections.valuation},{label:"SMART MONEY",...sections.smartMoney},{label:"POSITIONING",...sections.crowd}];
 return <section className={`dossier-synthesis ${synthesis.verdict}`} aria-label="Dossier cross-synthesis"><header><div><span className="eyebrow">CROSS-SYNTHESIS</span><h2>{synthesis.verdict.replace("_"," ").toUpperCase()}</h2></div><span>{a.delivery.cacheHit?"DAILY CACHE":"FRESH BUILD"} · {num(a.delivery.payloadBytes/1024,1)} KB · {num(a.delivery.durationMs,0)} MS</span></header><p className="synthesis-conclusion">{synthesis.conclusion}</p><div className="synthesis-grid">{rows.map(row=><article key={row.label}><small>{row.label}</small><b>{row.verdict.toUpperCase()}</b><p>{row.interpretedLine}</p><span>{row.supportingFigures.join(" · ")}</span></article>)}</div><div className="synthesis-invalidation"><b>WHAT INVALIDATES THE CALL</b><p>{synthesis.invalidation}</p></div></section>;
}

function MiniSpark({values,tone="neutral"}:{values:number[];tone?:"positive"|"negative"|"neutral"}){
 const rows=values.map((value,index)=>({index,value}));
 if(rows.length<2)return <span className="spark-empty">CHART UNAVAILABLE</span>;
 return <div className={`mini-spark ${tone}`} aria-hidden="true"><ResponsiveContainer width="100%" height="100%"><ComposedChart data={rows} margin={{top:3,right:2,bottom:3,left:2}}><Area type="monotone" dataKey="value" stroke="currentColor" fill="currentColor" fillOpacity={0.12} strokeWidth={2} isAnimationActive={false}/></ComposedChart></ResponsiveContainer></div>;
}
function MarketSmartMoney({openTab}:{openTab:(tab:Tab)=>void}){
 const brief=useQuery({queryKey:["market-day-brief"],queryFn:()=>api.getMarketDayBrief({}),staleTime:5*60*1000});
 if(brief.isPending)return <LoadingSkeleton label="Loading market-wide smart money evidence"/>;
 if(brief.error)return <section className="market-smart-money"><div className="error">Market-wide smart money view failed: {String(brief.error)}</div><button className="action" onClick={()=>void brief.refetch()}>RETRY</button></section>;
 const data=brief.data;
 if(!data)return <section className="market-smart-money"><div className="empty">Market-wide smart money evidence is unavailable.</div></section>;
 return <section className="market-smart-money" aria-label="Market-wide smart money view">
  <header><span className="eyebrow">MARKET-WIDE VIEW</span><h1>Smart money</h1><p>Retained filing reads across the tracked market, before narrowing to a ticker.</p></header>
  <div className="smart-market-read"><div><small>POSTURE</small><strong>{data.smartMoney.posture}</strong></div><div><small>RETAINED FILING READS</small><strong>{data.smartMoney.evidenceCount}</strong></div><div><small>MARKET DIRECTION</small><strong>{data.direction}</strong></div><div><small>TRACKED BREADTH</small><strong>{data.breadth.percent==null?"—":`${num(data.breadth.percent)}%`}</strong></div></div>
  <div className="notice"><b>EVIDENCE BASIS</b><p>{data.smartMoney.note}</p><span>{data.breadth.basis}</span></div>
  <div className="smart-market-actions"><button className="action" onClick={()=>openTab("MARKET")}>OPEN MARKET HOME</button><button className="secondary" onClick={()=>openTab("NEWS")}>OPEN NEWS</button></div>
 </section>;
}
function MarketHome({choose,openTab}:{choose:(q:string)=>void;openTab:(tab:Tab)=>void}){
 const initialCache=useMemo(()=>readMarketBriefCache(),[]);
 const brief=useQuery({queryKey:["market-day-brief-bounded"],queryFn:loadMarketBriefWithTimeout,staleTime:5*60*1000,initialData:initialCache??undefined,initialDataUpdatedAt:initialCache?0:undefined,retry:false});
 const [sector,setSector]=useState<string|null>(null); const [showMethod,setShowMethod]=useState(false);
 const loaded=brief.data; const data=loaded?.brief;
 if(brief.isPending)return <section className="market-home market-loading"><div className="market-loading-copy"><span className="loading-dot"/><b>LOADING MARKET VIEW</b><p>Waiting up to {timeoutSeconds(MARKET_BRIEF_TIMEOUT_MS)} seconds for runners, sectors and breadth.</p></div></section>;
 if(!data)return <section className="market-home"><div className="error">{brief.error?String(brief.error).replace(/^Error:\s*/,""):"Market data is unavailable and no cached brief exists."}</div><button className="action" onClick={()=>void brief.refetch()}>RETRY MARKET DATA</button></section>;
 const freshness=regimeFreshness(data.regime.asOf,data.indexAlignment.indexes.map(row=>row.asOf));
 const selectedSector=data.sectors.find(row=>row.sector===sector)??null;
 const refresh=()=>{void brief.refetch()};
 const source=loaded?.source??"live", cachedAt=loaded?.cachedAt??data.generatedAt, fallbackReason=loaded?.fallbackReason??null;
 const runners=[...data.runners.gainers.map(row=>({...row,side:"gainer" as const})),...data.runners.losers.map(row=>({...row,side:"loser" as const}))];
 return <div className="market-home">
  <div className={`market-load-status ${source}`} role="status"><b>{source==="cached"?"CACHED MARKET BRIEF":"MARKET BRIEF UPDATED"}</b><span>{source==="cached"?`Saved ${asOfLabel(cachedAt)} · source session ${data.runners.asOf?dateLabel(data.runners.asOf):"unavailable"}`:`Generated ${asOfLabel(data.generatedAt)}`}</span>{fallbackReason&&<small>{fallbackReason}</small>}{brief.isFetching&&<small>Checking for a newer brief in the background…</small>}</div>
  <section className={`market-open ${data.direction}`} aria-label="Market overview">
   <header><div><span className="eyebrow">LATEST COMPLETED SESSION · {data.runners.asOf?dateLabel(data.runners.asOf):"DATE UNAVAILABLE"}</span><h1>{data.direction==="bullish"?"Buyers have the tape":data.direction==="bearish"?"Sellers have the tape":"A split tape rewards selection"}</h1></div><button className="refresh-market" onClick={refresh} disabled={brief.isFetching}>{brief.isFetching?"REFRESHING…":"REFRESH"}</button></header>
   <div className="market-glance">
    <button onClick={()=>choose("SPY")} aria-label="Open SPY dossier from market direction"><small>MARKET READ</small><strong>{data.direction}</strong><span>{data.indexAlignment.bullish}/{data.indexAlignment.measured} indexes bullish</span></button>
    <button onClick={()=>openTab("SIGNAL TAPE")} aria-label="Open signal tape for tracked breadth"><small>TRACKED BREADTH</small><strong>{data.breadth.percent==null?"—":`${num(data.breadth.percent)}%`}</strong><span>{data.breadth.advancing} of {data.breadth.measured} advancing</span></button>
    <button onClick={()=>setShowMethod(value=>!value)} aria-expanded={showMethod} aria-label="Show market regime evidence"><small>REGIME</small><strong className={freshness.stale?"neg":""}>{freshness.stale?"STALE":data.regime.phase}</strong><span>{data.regime.asOf?`as of ${dateLabel(data.regime.asOf)}`:"unavailable"}</span></button>
    <button onClick={()=>openTab("SMART MONEY")} aria-label="Open smart money view"><small>SMART MONEY</small><strong>{data.smartMoney.posture}</strong><span>{data.smartMoney.evidenceCount} retained filing reads</span></button>
   </div>
   {showMethod&&<div className="market-method" role="status"><b>{freshness.stale?"REGIME NEEDS A NEWER SESSION":"REGIME INPUTS CURRENT"}</b><p>{data.regime.note}</p><span>{data.breadth.basis}</span></div>}
  </section>

  <section className="runner-section" aria-label="Top daily runners">
   <div className="market-section-head"><div><span className="eyebrow">TRACKED UNIVERSE</span><h2>Top runners</h2></div><button onClick={()=>openTab("SIGNAL TAPE")}>OPEN ALL SIGNALS</button></div>
   {runners.length?<div className="runner-grid">{runners.map(row=><button className={`runner-card ${row.side}`} key={row.symbol} onClick={()=>choose(row.symbol)} aria-label={`Open ${row.symbol} dossier, ${pct(row.changePercent)} today`}><div className="runner-copy"><span><b>{row.symbol}</b><small>{row.name}</small></span><strong className={row.changePercent>=0?"pos":"neg"}>{pct(row.changePercent)}</strong></div><MiniSpark values={row.sparkline} tone={row.changePercent>=0?"positive":"negative"}/><footer><span>{row.sector}</span><span>{row.side==="gainer"?"LEADER":"LAGGARD"} · {dateLabel(row.asOf)}</span></footer></button>)}</div>:<div className="empty"><b>Daily runners are unavailable.</b><span>Run a completed broad scan to populate the tracked cohort and its cached price history.</span><button onClick={()=>openTab("SIGNAL TAPE")}>OPEN AUTO SCAN</button></div>}
  </section>

  <section className="sector-section" aria-label="Top sectors">
   <div className="market-section-head"><div><span className="eyebrow">SECTOR MOMENTUM</span><h2>Where strength is clustering</h2></div><span>DAILY AVG · TRACKED COHORT</span></div>
   {data.sectors.length?<div className="sector-strip">{data.sectors.map(row=><button className={sector===row.sector?"active":""} key={row.sector} onClick={()=>setSector(current=>current===row.sector?null:row.sector)} aria-expanded={sector===row.sector} aria-label={`Open ${row.sector} sector detail`}><div><b>{row.sector}</b><strong className={(row.dailyChange??0)>=0?"pos":"neg"}>{pct(row.dailyChange)}</strong></div><MiniSpark values={row.sparkline} tone={(row.dailyChange??0)>=0?"positive":"negative"}/><span>{row.breadth==null?"breadth unavailable":`${num(row.breadth)}% advancing`} · {row.measured} names</span></button>)}</div>:<div className="empty">Sector reads are unavailable until a tracked scan cohort has usable histories.</div>}
   {selectedSector&&<div className="sector-detail"><div><span className="eyebrow">{selectedSector.sector}</span><h3>{pct(selectedSector.dailyChange)} average move · {selectedSector.advancing}/{selectedSector.measured} advancing</h3></div><div>{selectedSector.notable.map(item=><button key={item.symbol} onClick={()=>choose(item.symbol)}><b>{item.symbol}</b><span>{pct(item.return15d)} / 15 sessions</span></button>)}</div></div>}
  </section>

  <section className="chart-brief" aria-label="Market day charts">
   <div className="market-section-head"><div><span className="eyebrow">MARKET DAY BRIEF</span><h2>Indexes and breadth</h2></div><button onClick={()=>setShowMethod(value=>!value)}>{showMethod?"HIDE METHOD":"SHOW METHOD"}</button></div>
   <div className="index-chart-grid">{data.indexAlignment.indexes.map(row=><button key={row.symbol} onClick={()=>choose(row.symbol)} aria-label={`Open ${row.symbol} index dossier`}><header><b>{row.symbol}</b><strong className={(row.return15d??0)>=0?"pos":"neg"}>{pct(row.return15d)} <small>15D</small></strong></header><MiniSpark values={row.sparkline} tone={(row.return15d??0)>=0?"positive":"negative"}/><footer><span>{row.direction??"unrated"}</span><span>{row.asOf?dateLabel(row.asOf):"—"}</span></footer></button>)}</div>
   <button className="breadth-chart" onClick={()=>openTab("SIGNAL TAPE")} aria-label="Open signal tape behind tracked breadth"><div><span><i className="advance" style={{width:`${data.breadth.percent??0}%`}}/></span></div><strong>{data.breadth.advancing} advancing</strong><strong>{Math.max(0,data.breadth.measured-data.breadth.advancing)} declining</strong><small>{data.breadth.basis}</small></button>
   {showMethod&&<div className="market-method"><p>{data.bullets[0]?.text??data.breadth.basis}</p><span>Generated {asOfLabel(data.generatedAt)}</span></div>}
  </section>
 </div>;
}

function _Home({choose,openTape,openTab}:{choose:(q:string)=>void;openTape:(q:string)=>void;openTab:(tab:Tab)=>void}){
 const market=useQuery({queryKey:["market-read","home"],queryFn:()=>api.getMarketRead({}),staleTime:5*60*1000});
 const scan=useQuery({queryKey:["auto-scan"],queryFn:()=>api.getAutoScan({}),staleTime:5*60*1000});
 const watch=useQuery({queryKey:["watchlist-rows"],queryFn:()=>api.getWatchlistRows({}),staleTime:5*60*1000});
 const hits=useQuery({queryKey:["engine-hits"],queryFn:()=>api.getEngineHits({}),staleTime:5*60*1000});
 const active=(scan.data?.signals??[]).slice(0,4);const leadingSignal=active[0];const latestHit=hits.data?.hits[0];
 return <div className="home">
  <section className="home-lead"><div className="market-title"><span className="eyebrow">MARKET PULSE</span>{market.data?.partial&&<span className="feed-status">PARTIAL FEED</span>}</div>{market.isPending?<LoadingSkeleton label="Building market summary"/>:market.error?<div className="error">Market summary failed: {String(market.error)}</div>:<><h1>{market.data?.synthesis}</h1><MetricGrid items={[{label:"15-session breadth",value:market.data?.breadth15d==null?"Unavailable":`${num(market.data.breadth15d)}%`,tone:(market.data?.breadth15d??0)>=50?"pos":"neg"},{label:"Active flags",value:String(market.data?.activeFlags??0)},{label:"Broad scan candidates",value:String(scan.data?.run?.signalCount??0)},{label:"Risk-adjusted leader",value:market.data?.leader??"—"}]}/><p className="subline">Live pulse {market.data?new Date(market.data.refreshedAt).toLocaleString():"—"} · broad discovery is prepared in the background.</p></>}</section>
  <div className="home-grid">
   <Section title="Prepared news / sector impact" right={<button className="secondary" onClick={()=>openTab("SIGNAL TAPE")}>OPEN DISCOVERY</button>}><div className="home-news">{scan.isPending?<div className="empty">LOADING PREPARED RESEARCH…</div>:scan.error?<div className="error">Prepared feed failed: {String(scan.error)}</div>:scan.data?.news.length?scan.data.news.slice(0,4).map(item=><article key={item.id}><div className="news-meta"><span>{item.source}</span><time>{new Date(item.publishedAt).toLocaleDateString()}</time></div><a href={item.url} target="_blank" rel="noreferrer"><h4>{item.title}</h4></a><p>{item.whyItMatters}</p></article>):<div className="empty">No completed background scan yet. Open Auto Scan and run S&amp;P 100.</div>}</div></Section>
   <Section title="Watchlist snapshot" right={<button className="secondary" onClick={()=>openTab("WATCHLIST")}>OPEN WATCHLIST</button>}><div className="home-list">{watch.isPending?<div className="empty">LOADING WATCHLIST…</div>:watch.error?<div className="error">Watchlist failed: {String(watch.error)}</div>:watch.data?.items.length?watch.data.items.slice(0,5).map(item=><button key={item.id} onClick={()=>choose(item.symbol)}><span><b>{item.symbol}</b><small>{item.name}</small></span><span>OPEN DOSSIER<small>refresh analysis on demand</small></span></button>):<div className="empty">Your watchlist is empty. Search an instrument, then add it from the dossier.</div>}</div></Section>
   <Section title="Broad-market signals" right={<button className="secondary" onClick={()=>leadingSignal&&openTape(leadingSignal.symbol)} disabled={!leadingSignal}>{leadingSignal?`OPEN ${leadingSignal.symbol} TAPE`:"RUN AUTO SCAN"}</button>}><div className="home-list">{scan.isPending?<div className="empty">LOADING RANKED SIGNALS…</div>:active.length?active.map(item=><button key={item.id} onClick={()=>choose(item.symbol)}><span><b>{item.symbol}</b><small>{item.sector} · {pct(item.return15d)} / 15 sessions</small></span><span className={item.ratingAvailable?(item.agreementScore>=0?"pos":"neg"):""}>{item.ratingAvailable?<>{item.agreementScore>0?"+":""}{item.agreementScore} · {directionLabel(item.direction)}</>:"NO DIRECTIONAL RATING"}<small>{item.ratingAvailable?`${item.confidenceTier.toUpperCase()} confidence · `:"coverage below 4/5 · "}{item.activeFlags} active {item.activeFlags===1?"setup":"setups"}</small></span></button>):<div className="empty">No ranked background signals yet.</div>}</div></Section>
   <Section title="Engine hits" right={<button className="secondary" onClick={()=>openTab("ENGINE HITS")}>OPEN LOG</button>}>{hits.isPending?<div className="empty">LOADING ENGINE HITS…</div>:hits.error?<div className="error">Engine hits failed: {String(hits.error)}</div>:latestHit?<button className="engine-hit-preview" onClick={()=>openTab("ENGINE HITS")}><span><b>{dateLabel(latestHit.hitAt)} · {latestHit.testCaseLabel}</b><small>{latestHit.thesis}</small></span><strong className="neg">{latestHit.kind==="gem"?`GEM ${latestHit.evidenceStrength??latestHit.engineScore}`:`${latestHit.confidenceTier.toUpperCase()} ${latestHit.engineScore}/100`}</strong></button>:<div className="empty">No engine hits logged yet</div>}</Section>
  </div>
 </div>
}

type EngineHit = ApiResponse<typeof api,"getEngineHits">["hits"][number];
function EngineHits(){
 const q=useQuery({queryKey:["engine-hits"],queryFn:()=>api.getEngineHits({}),staleTime:5*60*1000});
 return <><header className="engine-hits-head"><span className="eyebrow">THEORY WATCH · EVIDENCE LOG</span><h2>Engine Hits</h2><p>Events that materially support or challenge tracked theories, preserved with the score and tape state that existed when the hit landed.</p></header><div className="engine-hit-list">{q.isPending?<LoadingSkeleton label="Loading theory engine hits"/>:q.error?<div className="error">Engine hits failed: {String(q.error)}</div>:q.data.hits.length?q.data.hits.map(hit=><EngineHitCard key={hit.id} hit={hit}/>):<div className="empty engine-empty">No engine hits logged yet</div>}</div></>
}
function EngineHitCard({hit}:{hit:EngineHit}){if(hit.kind==="gem")return <article className="engine-hit-card gem-card"><header><div><span className="status live">EVIDENCE-BACKED GEM</span><time dateTime={hit.hitAt}>{dateLabel(hit.hitAt)}</time><h3>{hit.symbol??"Unlinked lead"} · {hit.anomaly??hit.triggerEvent}</h3></div><div className="engine-score"><small>EVIDENCE STRENGTH</small><strong>{hit.evidenceStrength??hit.engineScore}</strong></div></header><div className="tag-row">{hit.tags.map(tag=><span className="badge" key={tag}>{tag}</span>)}</div><div className="engine-thesis"><small>THESIS FIT · NOT A TRADE CALL</small><b>{hit.thesis}</b>{hit.lowTierEvidenceExcluded>0&&<span className="status challenged">{hit.lowTierEvidenceExcluded} LOW-TIER SOURCE{hit.lowTierEvidenceExcluded===1?"":"S"} EXCLUDED</span>}</div><section className="engine-evidence"><div className="section-head"><h3>Evidence bullets</h3><span>{hit.evidence.length} independent reads</span></div>{hit.evidence.map((source,index)=><a key={`${source.url}-${index}`} href={source.url} target="_blank" rel="noreferrer"><span>{String(index+1).padStart(2,"0")} · {source.source}</span><b>{source.title}</b><small>{source.supports}</small></a>)}</section></article>;return <article className="engine-hit-card"><header><div><span className="status live">{hit.testCaseLabel}</span><time dateTime={hit.hitAt}>{dateLabel(hit.hitAt)}</time><h3>{hit.triggerEvent}</h3></div><div className="engine-score"><small>ENGINE SCORE AT HIT</small><strong>{hit.confidenceTier.toUpperCase()} {hit.engineScore}/100</strong></div></header><div className="engine-thesis"><small>THESIS SUPPORTED</small><b>{hit.thesis}</b>{hit.lowTierEvidenceExcluded>0&&<span className="status challenged">{hit.lowTierEvidenceExcluded} LOW-TIER SOURCE{hit.lowTierEvidenceExcluded===1?"":"S"} EXCLUDED</span>}</div><div className="engine-tape"><span className="status challenged">TAPE DIVERGENCE</span><p>{hit.tapeState}</p></div><blockquote><b>THE TWIST</b>{hit.twist}</blockquote><section className="engine-chain" aria-label="Multi-hop ripple chain"><div className="section-head"><h3>Multi-hop ripple chain</h3><span>Evidence and inference stay separate</span></div>{hit.rippleChain.map((hop,index)=><div className={`engine-hop ${hop.kind}`} key={`${hop.from}-${index}`}><div className="engine-hop-index">{String(index+1).padStart(2,"0")}</div><div><div className="hop-head"><span className={`status ${hop.kind==="verified"?"confirming":"challenged"}`}>{hop.kind}</span>{hop.evidenceIndexes.length>0&&<small>{hop.evidenceIndexes.map(i=>hit.evidence[i]?.source).filter(Boolean).join(" + ")}</small>}</div><h4>{hop.from} → {hop.to}</h4><p>{hop.mechanism}</p>{hop.evidenceIndexes.length>0&&<div className="hop-sources">{hop.evidenceIndexes.map(i=>{const source=hit.evidence[i];return source?<a key={`${source.url}-${i}`} href={source.url} target="_blank" rel="noreferrer">{source.source}</a>:null})}</div>}</div></div>)}</section><section className="engine-evidence"><div className="section-head"><h3>Evidence links</h3><span>{hit.evidence.length} sources</span></div>{hit.evidence.map((source,index)=><a key={source.url} href={source.url} target="_blank" rel="noreferrer"><span>{String(index+1).padStart(2,"0")} · {source.source}</span><b>{source.title}</b><small>{source.supports}</small></a>)}</section></article>}

function Radar({choose,openTape}:{choose:(q:string)=>void;openTape:(q:string)=>void}){const q=useQuery({queryKey:["radar"],queryFn:()=>api.getRadar({}),staleTime:5*60*1000});return <Section title="Radar · 90+ retained evidence"><p className="subline">Qualifying tracked signals and scan results stay visible with their retained ledger, invalidation, and source time.</p>{q.data?.universe?.status==="degraded"&&<div className="scan-degraded" role="alert"><b>DEGRADED · DATA PIPELINE FAILURE</b><span>Zero usable histories were returned. This is not a no-signal market result. {q.data.universe.note}</span></div>}{q.data?.universe&&<div className="notice"><b>{q.data.universe.name.toUpperCase()} coverage · {q.data.universe.status.toUpperCase()}:</b> {q.data.universe.requestedCount} requested · {q.data.universe.scannedCount} scanned · {q.data.universe.availableCount} available · {q.data.universe.signalCount} retained · {q.data.universe.excludedCount} excluded{q.data.universe.exclusions.length?` (${q.data.universe.exclusions.map(x=>`${x.symbol}: ${x.reason}`).join("; ")})`:""}</div>}{q.data&&q.data.omittedUnverifiable>0&&<div className="notice">{q.data.omittedUnverifiable} 90+ {q.data.omittedUnverifiable===1?"row is":"rows are"} excluded. {q.data.omissionRule}</div>}<div className="radar-list">{q.isPending?<LoadingSkeleton label="Loading radar history"/>:q.error?<div className="error">Radar failed: {String(q.error)}</div>:q.data.items.length?q.data.items.map(item=><details className="radar-item" key={`${item.origin}-${item.id}`}><summary><div><b>{item.symbol} · {directionLabel(item.direction)}</b><small>{item.origin==="tracker"?`TRACKED SIGNAL · ${new Date(item.scanCreatedAt).toLocaleString()}`:`${item.sector??"Sector unavailable"} · scan #${item.runId??"—"} · ${item.universe?.toUpperCase()??"UNIVERSE UNAVAILABLE"} · ${new Date(item.scanCreatedAt).toLocaleString()}`}</small></div><strong className={item.agreementScore>=0?"pos":"neg"}>{item.agreementScore>0?"+":""}{item.agreementScore}</strong></summary><div className="radar-detail"><Reliability score={item.agreementScore}/>{item.rawScore!=null&&<div className="notice formula">Raw {item.rawScore>0?"+":""}{item.rawScore} · redundancy adjustment {item.redundancyAdjustment&&item.redundancyAdjustment>0?"+":""}{item.redundancyAdjustment??0} · final {item.agreementScore>0?"+":""}{item.agreementScore}</div>}<div className="signal-safeguards"><span className={isStale(item.sourceAsOf)?"stale":"fresh"}>{isStale(item.sourceAsOf)?"STALE":"FRESH"}</span><span>As of {asOfLabel(item.sourceAsOf)}</span><span>Invalidation {money(item.invalidationLevel)}</span>{item.sourceUrl?<a href={item.sourceUrl} target="_blank" rel="noreferrer">Evidence / disconfirmation source</a>:<span>Evidence link unavailable</span>}</div><div className="factor-disclosure"><b>Score formula</b><small>{item.formula}</small>{item.factors.map(factor=><div className="factor-row" key={factor.name}><span><b>{factor.name}</b><small>{factor.reading}</small></span><span>w {num(factor.weight,3)} × {factor.score>0?"+":""}{factor.score} = <b className={factor.contribution>0?"pos":factor.contribution<0?"neg":""}>{factor.contribution>0?"+":""}{num(factor.contribution,3)}</b></span></div>)}</div><div className="form-actions"><button className="secondary" onClick={()=>choose(item.symbol)}>DOSSIER</button><button className="secondary" onClick={()=>openTape(item.symbol)}>SIGNAL TAPE</button></div></div></details>):<div className="empty">No retained signal currently reaches ±{q.data.threshold} with the required evidence. {q.data.omissionRule}</div>}</div></Section>}

function AutoScan({choose,openTape,qc}:{choose:(q:string)=>void;openTape:(q:string)=>void;qc:ReturnType<typeof useQueryClient>}){
 const q=useQuery({queryKey:["auto-scan"],queryFn:()=>api.getAutoScan({})});
 const [scope,setScope]=useState<"sp100"|"sp500">("sp100");
 const [tierView,setTierView]=useState<"t1"|"t2"|"t3">("t1");
 const run=useMutation({mutationFn:()=>api.runAutomatedScan({universe:scope}),onSuccess:()=>{qc.invalidateQueries({queryKey:["auto-scan"]});qc.invalidateQueries({queryKey:["machine-theories"]});qc.invalidateQueries({queryKey:["tracker"]});qc.invalidateQueries({queryKey:["radar"]});qc.invalidateQueries({queryKey:["alerts"]})}});
 const data=run.data??q.data;
 const tierRows=data?.tiers[tierView]??[]; const detailedSignals=data?.signals.filter(signal=>signal.universeTier===tierView)??[];
 return <><header className="scan-head"><div><span className="eyebrow">AUTOMATED DISCOVERY</span><h2>Broad tape, ranked before you open it.</h2><p>Every candidate is tested across trend, momentum, volatility, volume, and positioning/sentiment before it receives a confidence tier. Low-confidence names are retained as research leads, not hidden.</p></div><div className="scan-controls"><div className="view-switch"><button className={scope==="sp100"?"active":""} onClick={()=>setScope("sp100")}>S&amp;P 100</button><button className={scope==="sp500"?"active":""} onClick={()=>setScope("sp500")}>S&amp;P 500</button></div><button className="action" onClick={()=>run.mutate()} disabled={run.isPending}>{run.isPending?`SCANNING ${scope==="sp100"?"100":"500"}…`:"RUN FULL SCAN"}</button></div></header>
 {run.isPending&&<div className="scan-progress"><b>Research run in progress</b><span>Membership → Yahoo history → five-dimension gate → confidence tier → current news → sector synthesis → direct theory discovery. You can leave this tab; scheduled S&amp;P 100 scans also keep the cache warm.</span></div>}
 {run.error&&<div className="error">Automatic scan failed: {String(run.error)}</div>}
 {!data?.run?<div className="instrument-prompt"><span className="eyebrow">NO COMPLETED RUN</span><h2>Start with the S&amp;P 100.</h2><p>The first run creates the prepared signal, news, sector-impact and theory cache. Nothing is filled with sample market data.</p><button className="action" onClick={()=>run.mutate()} disabled={run.isPending}>RUN S&amp;P 100</button></div>:<><section className={`scan-summary ${data.run.status}`}><div className="market-title"><div><span className="eyebrow">{data.run.universe.toUpperCase()} · {data.run.status}</span><h2>{data.run.signalCount} ranked candidates from {data.run.availableCount} usable charts</h2></div><a href={data.run.sourceUrl} target="_blank" rel="noreferrer">UNIVERSE SOURCE</a></div>{data.run.status==="degraded"&&<div className="scan-degraded" role="alert"><b>DEGRADED · DATA PIPELINE FAILURE</b><span>Zero usable histories were returned. This run is not evidence that the market had no signals.</span></div>}<MetricGrid items={[{label:"Constituents",value:String(data.run.requestedCount)},{label:"Usable histories",value:String(data.run.availableCount)},{label:"Ranked candidates",value:String(data.run.signalCount)},{label:"Prepared news",value:String(data.run.newsCount)}]}/><p className="subline">Completed {new Date(data.run.createdAt).toLocaleString()} · {data.run.note}</p>{data.theoryRun&&<p className="subline">Theory engine: {data.theoryRun.status} · {data.theoryRun.surfacedCount} surfaced · {data.theoryRun.withheldFloorCount} floor-withheld · {data.theoryRun.contestedCount} contested · {data.theoryRun.note}</p>}</section>
 <Section title="Universe tiers"><div className="tier-explainer"><b>Effort lanes, not scoring changes</b><span>{data.tiers.methodology}</span></div><div className="tier-tabs" aria-label="Equity universe tiers">{(["t1","t2","t3"] as const).map(tier=><button key={tier} className={tierView===tier?"active":""} onClick={()=>setTierView(tier)}><b>{tier.toUpperCase()}</b><span>{data.tiers[tier].length}</span><small>{tier==="t1"?"FULL + RESEARCH":tier==="t2"?"VELOCITY → FULL":"LIGHTWEIGHT"}</small></button>)}</div><div className="tier-roster" aria-label={`${tierView.toUpperCase()} universe members`}>{tierRows.map(item=><button key={item.symbol} onClick={()=>choose(item.symbol)} aria-label={`Open ${item.symbol} dossier`}><span><b>{item.symbol}</b><small>{item.name} · {item.sector}</small></span><span><strong>{item.velocity5d==null?"NO VELOCITY":`${item.velocity5d>=0?"+":""}${num(item.velocity5d)}%`}</strong><small>{item.trackingMode.toUpperCase()}</small></span></button>)}</div>{!tierRows.length&&<div className="empty">This run predates tier tracking. Run a fresh scan to organize every constituent into T1, T2, or T3.</div>}</Section>
 <Section title={tierView==="t3"?"T3 lightweight watchlist":"Five-dimension signal gate"}><div className="method-strip"><b>{tierView==="t3"?"Lightweight tracking":"Five-dimension gate"}</b><span>{tierView==="t3"?"T3 preserves below-qualifier names with the five-session velocity read only. It does not assign a directional score or issue a signal.":"A directional rating needs at least 4 of 5 dimensions measured. Missing evidence remains in the denominator; 100 is reserved for all five measured and aligned. Unrated candidates stay visible as research leads."}</span></div><div className="scan-signal-grid">{detailedSignals.map((item,index)=><article className={`scan-signal confidence-${item.confidenceTier}`} key={item.id}><button className="scan-open" onClick={()=>choose(item.symbol)} aria-label={`Open ${item.symbol} dossier`}><div><span className="scan-rank">#{index+1}</span><b>{item.symbol}</b><small>{item.name} · {item.sector}</small></div><div className="signal-score"><span className="status universe-tier">{item.universeTier.toUpperCase()}</span><span className={`status tier-${item.confidenceTier}`}>{item.confidenceTier} confidence</span><strong className={item.ratingAvailable?(item.agreementScore>=0?"pos":"neg"):""}>{item.ratingAvailable?<>{item.agreementScore>0?"+":""}{item.agreementScore} · {directionLabel(item.direction)}</>:"NO DIRECTIONAL RATING"}</strong></div></button><p>{item.why}</p>{item.ratingAvailable&&<Reliability score={item.agreementScore}/>}<div className="signal-safeguards"><span className={isStale(item.sourceAsOf)?"stale":"fresh"}>{isStale(item.sourceAsOf)?"STALE":"FRESH"}</span><span>As of {asOfLabel(item.sourceAsOf)}</span><span>Invalidation {money(item.invalidationLevel)}</span>{item.sourceUrl?<a href={item.sourceUrl} target="_blank" rel="noreferrer">Evidence / disconfirmation source</a>:<span>Evidence link unavailable</span>}</div><div className="factor-disclosure"><b>Score formula</b><small>{item.formula}</small>{item.factors.map(factor=><div className="factor-row" key={factor.name}><span><b>{factor.name}</b><small>{factor.reading}</small></span><span>w {num(factor.weight,3)} × {factor.score>0?"+":""}{factor.score} = <b className={factor.contribution>0?"pos":factor.contribution<0?"neg":""}>{factor.contribution>0?"+":""}{num(factor.contribution,3)}</b></span></div>)}</div><div className="dimension-grid">{item.dimensions.map(dimension=><div key={dimension.name}><span className={`status ${dimension.status==="supports"?"confirming":dimension.status==="conflicts"?"refuted":"challenged"}`}>{dimension.status}</span><b>{dimension.name}</b><small>{dimension.detail}</small></div>)}</div>{item.researchRequired.length>0&&<p className="research-gap"><b>Research required:</b> {item.researchRequired.join(", ")}</p>}<div className="form-actions"><button className="secondary" onClick={()=>choose(item.symbol)}>DOSSIER</button><button className="secondary" onClick={()=>openTape(item.symbol)}>SIGNAL TAPE</button></div></article>)}</div>{!detailedSignals.length&&<div className="empty">{tierView==="t3"?"T3 intentionally has no full directional scores. Use the roster above for lightweight velocity tracking or open a dossier for one name.":`No ${tierView.toUpperCase()} name survived the existing completeness and issuance gates in this run.`}</div>}</Section>
 <Section title="Sector impact"><div className="sector-impact-grid">{data.sectors.map(item=><article className={`sector-impact ${item.direction}`} key={item.id}><div><span className={`status ${item.direction==="positive"?"confirming":item.direction==="negative"?"refuted":"challenged"}`}>{item.direction}</span><b>{item.sector}</b><strong className={item.evidenceScore>=0?"pos":"neg"}>{item.evidenceScore>0?"+":""}{item.evidenceScore}</strong></div><h4>{item.headline}</h4><p>{item.reason}</p><small>{item.sourceCount} directly supporting news {item.sourceCount===1?"row":"rows"} · score is signed evidence agreement, not probability</small></article>)}</div></Section>
 <Section title="Prepared news"><div className="news-list">{data.news.map(item=><article className="news-item" key={item.id}><div className="news-meta"><span>{item.source}</span><time>{item.timestampKind==="published"?"Published":"Retrieved"} {new Date(item.publishedAt).toLocaleString()}</time></div><a href={item.url} target="_blank" rel="noreferrer"><h4>{item.title}</h4></a><p><b>Why it matters:</b> {item.whyItMatters}</p><div className="tag-row">{item.ripples.map(tag=><span className="badge" key={tag}>{tag}</span>)}</div></article>)}</div>{!data.news.length&&<div className="empty">The news source lane returned no rows; the chart scan remains available.</div>}</Section></>}
 </>
}
function PrivatePanel({data,choose}:{data:NonNullable<Analysis["privateCompany"]>;choose:(q:string)=>void}){return <><header className="hero"><div className="eyebrow">PRIVATE COMPANY</div><h2>{data.name}</h2><p className="prose">{data.description}</p></header><Section title="Funding status"><div className="panel"><p className="prose">{data.fundingStatus}</p></div></Section><Section title="Closest public exposure"><div className="private-grid">{data.exposures.map(x=><button key={x.ticker} onClick={()=>choose(x.ticker)}><b className="mono cyan">{x.ticker}</b><p className="subline">{x.why}</p></button>)}</div></Section><Section title="Sources"><div className="list sources">{data.sources.map(s=><a key={s.url} href={s.url} target="_blank" rel="noreferrer">{s.title}</a>)}</div></Section></>}
type TapeItem=ApiResponse<typeof api,"getInstrumentSignals">["signals"][number];
function SignalTape({query,openDossier}:{query:string;openDossier:()=>void}){const [filter,setFilter]=useState<"ALL"|"BULLISH"|"BEARISH"|"PINNED">("ALL");const [pinned,setPinned]=useState<string[]>([]);const q=useQuery({queryKey:["signal-tape",query],queryFn:()=>api.getInstrumentSignals({query})});const shown=(q.data?.signals??[]).filter(x=>filter==="ALL"||(filter==="PINNED"?pinned.includes(x.id):x.direction===filter.toLowerCase()));return <><Section title="Signal tape"><div className="filter-row" aria-label="Signal filters">{(["ALL","BULLISH","BEARISH","PINNED"] as const).map(x=><button key={x} className={filter===x?"active":""} onClick={()=>setFilter(x)}>{x}</button>)}</div>{q.data&&<div className="notice">{q.data.disclaimer} Source as of {q.data.sourceAsOf?new Date(q.data.sourceAsOf).toLocaleString():"unavailable"}.</div>}<div className="signal-list">{q.isPending?<LoadingSkeleton label="Calculating testable setups"/>:q.error?<div className="error">Signal tape failed: {String(q.error)}</div>:shown.length?shown.map(signal=><SignalCard key={signal.id} signal={signal} sourceAsOf={q.data?.sourceAsOf??null} sourceUrl={q.data?.sourceUrl??null} pinned={pinned.includes(signal.id)} togglePin={()=>setPinned(items=>items.includes(signal.id)?items.filter(id=>id!==signal.id):[...items,signal.id])} openDossier={openDossier}/>):<div className="empty">No signals match this filter. Choose another filter or analyze a listed symbol.</div>}</div></Section></>}
function SignalCard({signal,sourceAsOf,sourceUrl,pinned,togglePin,openDossier}:{signal:TapeItem;sourceAsOf:string|null;sourceUrl:string|null;pinned:boolean;togglePin:()=>void;openDossier:()=>void}){const rated=signal.alignmentScore!=null;return <details className={`signal-card ${signal.active?"active-signal":""}`}><summary><div className="signal-main"><span className={`direction ${signal.direction}`}>{rated?signal.direction:"coverage incomplete"}</span><h4>{signal.name}</h4><p>{signal.aligned} aligned · {signal.conflicts} conflicts · {signal.measured}/5 measured</p></div><div className="signal-score"><b>{rated?`${signal.direction==="bearish"?"−":"+"}${signal.alignmentScore} · ${signal.direction.toUpperCase()}`:"NO DIRECTIONAL RATING"}</b><span>{rated?`${signal.alignmentLabel} confidence`:"minimum 4/5 required"}</span></div></summary><div className="signal-detail">{signal.unavailableReason&&<div className="notice">Unavailable: {signal.unavailableReason}</div>}<div className="signal-safeguards"><span className={isStale(sourceAsOf)?"stale":"fresh"}>{isStale(sourceAsOf)?"STALE":"FRESH"}</span><span>As of {asOfLabel(sourceAsOf)}</span><span>Invalidation {money(signal.invalidation)}</span>{signal.invalidationBasis&&<span>{signal.invalidationBasis}</span>}{sourceUrl?<a href={sourceUrl} target="_blank" rel="noreferrer">Evidence / disconfirmation source</a>:<span>Evidence link unavailable</span>}</div>{signal.alignmentScore!=null&&<Reliability score={signal.alignmentScore}/>}<div className="check-breakdown"><b>{signal.aligned}/5 required dimensions support · {signal.measured}/5 measured</b><small>Score formula: 100 × supporting dimensions ÷ all 5 required dimensions. Unavailable evidence stays in the denominator. A rating is withheld below 4/5 measured; 100 requires 5/5 measured and aligned.</small>{signal.checks.map(check=><div key={check.label}><span className={`status ${check.status==="supports"?"confirming":check.status==="conflicts"?"refuted":"challenged"}`}>{check.status}</span><span>{check.label}</span></div>)}</div><p><b>Empirical read:</b> {signal.empiricalRead}</p><p><b>Thesis:</b> {signal.thesis}</p><p className="neg"><b>Failure:</b> {signal.failure}</p><MetricGrid items={[{label:"Entry zone",value:signal.entryLow==null||signal.entryHigh==null?"Unavailable":`${money(signal.entryLow)}–${money(signal.entryHigh)}`},{label:"Invalidation",value:money(signal.invalidation),tone:"neg"},{label:"Target 1 (signal model)",value:money(signal.target1)},{label:"Target 2 (signal model)",value:money(signal.target2)}]}/><div className="form-actions"><button className="secondary" onClick={e=>{e.preventDefault();togglePin()}}>{pinned?"UNPIN":"PIN SETUP"}</button><button className="action" onClick={e=>{e.preventDefault();openDossier()}}>OPEN DOSSIER</button></div></div></details>}

function WalkForwardAudit({data,symbol}:{data:NonNullable<Analysis["walkForward"]>;symbol:string}){
 const [rows,setRows]=useState(data.decisions);const [nextOffset,setNextOffset]=useState<number|null>(0);
 const older=useMutation({mutationFn:(offset:number)=>api.getWalkForwardDecisions({symbol,offset,limit:50}),onSuccess:(page)=>{setRows(current=>page.offset===0?page.decisions:[...current,...page.decisions]);setNextOffset(page.nextOffset)}});
 const load=()=>older.mutate(nextOffset??0);
 return <Section title="Walk-forward audit trail"><div className="walk-audit-summary"><div><small>OBSERVATION SET</small><b>{data.observations} decisions · {data.hitRate==null?"hit rate unavailable":`${num(data.hitRate)}% directional hits`}</b><span>{data.averageDirectionalReturn==null?"Average directional return unavailable":`${pct(data.averageDirectionalReturn)} average directional return`}</span></div><div><small>FIXED SOURCE WINDOW</small><b>{data.dataWindow.firstUsableDate??"Unavailable"} → {data.dataWindow.lastSourceDate??"Unavailable"}</b><span>{num(data.dataWindow.sourceSessions,0)} source sessions · floor {data.dataWindow.fixedStart}</span></div></div><div className="notice walk-note"><b>VERDICT:</b> {data.qualified?`Qualified across ${data.observations} frozen weekly decisions.`:`Withheld; ${data.observations}/20 decisions available.`}<br/><b>No-lookahead rule:</b> {data.decisionRule}</div><details className="walk-decisions"><summary>RECENT DECISIONS · {data.decisions.length}</summary><div className="walk-table" role="table" aria-label="Walk-forward decisions and outcomes"><div className="walk-row walk-head" role="row"><span>Decision close</span><span>Outcome close</span><span>Score / side</span><span>Entry → outcome</span><span>Directional return</span></div>{rows.map((row,index)=><div className="walk-row" role="row" key={`${row.decisionAt}-${index}`}><time>{row.decisionAt}</time><time>{row.outcomeAt}</time><span>{row.score>0?"+":""}{row.score} · {row.direction.toUpperCase()}</span><span>{num(row.entryClose,4)} → {num(row.outcomeClose,4)}</span><strong className={row.directionalReturnPct>=0?"pos":"neg"}>{pct(row.directionalReturnPct)}</strong></div>)}</div><button className="secondary" onClick={load} disabled={older.isPending||nextOffset==null}>{older.isPending?"LOADING…":nextOffset==null?"FULL HISTORY LOADED":"LOAD FULL HISTORY"}</button></details><p className="subline">The dossier carries only the latest 20 decisions. Older rows load from the paginated drill-in action.</p></Section>;
}

type CrowdPricingData=Analysis["crowdPricing"];
function CrowdPricingPanel({data}:{data:CrowdPricingData}){const renderMarket=(market:CrowdPricingData["fedDecision"][number])=><article className="crowd-market" key={market.slug}><div><h4>{market.question}</h4><span>Yes implied crowd price <b>{market.yesImpliedCrowdPrice.toFixed(4)}</b> · No implied crowd price <b>{market.noImpliedCrowdPrice.toFixed(4)}</b></span></div><div className="crowd-market-stats"><span>24h volume <b>${num(market.volume24hr,0)}</b></span><span>Liquidity <b>${num(market.liquidity,0)}</b></span></div><a href={market.marketUrl} target="_blank" rel="noreferrer">POLYMARKET SOURCE</a></article>;return <Section title="Macro odds · crowd pricing"><div className="notice crowd-label">{data.label}</div>{data.state==="no_data"?<div className="empty"><b>NO CROWD-PRICING DATA</b><p>{data.reason}</p></div>:<><div className="crowd-group"><div className="crowd-group-head"><b>NEXT FED DECISION</b><span>{data.asOf?`As of ${asOfLabel(data.asOf)}`:"Timestamp unavailable"}</span></div>{data.fedDecision.length?data.fedDecision.map(renderMarket):<div className="empty">No Fed-decision outcome passed the liquidity gate.</div>}</div>{data.macroContext.length>0&&<div className="crowd-group"><div className="crowd-group-head"><b>MACRO CONTEXT</b><span>Up to two liquid markets</span></div>{data.macroContext.map(renderMarket)}</div>}{data.reason&&<p className="subline">Partial source note: {data.reason}</p>}</>}{data.sentiment&&<div className="sentiment-context"><b>FEAR &amp; GREED · {num(data.sentiment.value,0)} · {data.sentiment.classification}</b><span>As of {asOfLabel(data.sentiment.asOf)}</span><p>{data.sentiment.note}</p><a href={data.sentiment.sourceUrl} target="_blank" rel="noreferrer">ALTERNATIVE.ME SOURCE</a></div>}</Section>}
function Dossier({a,mode,setMode}:{a:Analysis;mode:"line"|"candles";setMode:(x:"line"|"candles")=>void}){const symbol=a.instrument?.symbol??"";const live=useQuery({queryKey:["market-freshness",symbol],queryFn:()=>api.getMarketFreshness({symbol}),enabled:!!symbol,staleTime:30*1000});if(!a.instrument)return null;const liveCandle=live.data?.symbols[0]?.inputs.find(input=>input.kind==="forming_candle")??live.data?.symbols[0]?.inputs.find(input=>input.kind==="completed_candle");const liveDate=sessionDateKey(liveCandle?.eventAt);const chart=liveCandle&&!liveCandle.stale&&liveDate?a.chart.map(point=>point.date===liveDate?{...point,close:liveCandle.close??point.close,high:liveCandle.high??point.high,volume:liveCandle.volume??point.volume}:point):a.chart;const currentRegime=a.factorModel?.direction==="long"?"Bullish regime":a.factorModel?.direction==="short"?"Bearish regime":"Mixed regime";return <>
 <details className="context-stack"><summary>CONTEXT · CHART, HISTORY, MACRO + BASE RATES</summary>
 <Section title={`Price + regime · ${a.instrument.currency??"currency unavailable"} adjusted close`} right={<div className="toggle"><button className={mode==="line"?"active":""} onClick={()=>setMode("line")}>CLOSE</button><button className={mode==="candles"?"active":""} onClick={()=>setMode("candles")}>HIGH</button></div>}><div className="regime-strip"><b>{currentRegime}</b><span>Regime is the signed factor agreement across price trend, momentum, RSI, MACD and volume.</span></div><div className="panel"><div className="chart-wrap"><ResponsiveContainer><ComposedChart data={chart}><CartesianGrid stroke="var(--border)" vertical={false}/><XAxis dataKey="date" tickFormatter={dateLabel} minTickGap={38} stroke="var(--dim)" fontSize={10}/><YAxis yAxisId="p" domain={["auto","auto"]} stroke="var(--dim)" fontSize={10} width={54} label={{value:a.instrument.currency??"N/A",angle:-90,position:"insideLeft",fill:"var(--dim)",fontSize:9}}/><YAxis yAxisId="v" orientation="right" hide domain={[0,"dataMax"]}/><Tooltip labelFormatter={(x)=>String(x)} contentStyle={{background:"var(--surface)",border:"1px solid var(--border)",fontFamily:"IBM Plex Mono"}}/><Legend/>{a.events.filter(e=>chart.some(p=>p.date===e.date)).map(e=><ReferenceLine key={`${e.type}-${e.date}`} yAxisId="p" x={e.date} stroke={e.type==="Split"?"var(--amber)":"var(--cyan)"} strokeDasharray="3 3" label={{value:e.type.slice(0,3).toUpperCase(),fill:"var(--dim)",fontSize:9}}/>)}{mode==="line"?<Area isAnimationActive={false} yAxisId="p" dataKey="close" name="Close" stroke="var(--accent)" fill="rgba(109,255,114,.08)" dot={false}/>:<Line isAnimationActive={false} yAxisId="p" dataKey="high" name="High" stroke="var(--cyan)" dot={false}/>}<Line isAnimationActive={false} yAxisId="p" dataKey="sma20" name="SMA 20" stroke="#f4c95d" dot={false}/><Line isAnimationActive={false} yAxisId="p" dataKey="sma50" name="SMA 50" stroke="#ff8d5a" dot={false}/><Line isAnimationActive={false} yAxisId="p" dataKey="sma200Proxy" name="200d" stroke="#a88cff" dot={false}/><Bar isAnimationActive={false} yAxisId="v" dataKey="volume" name="Volume" fill="rgba(50,204,232,.22)"/></ComposedChart></ResponsiveContainer></div></div></Section>
 <HistoricalContext symbol={a.instrument.symbol} currency={a.instrument.currency}/>
 <CycleClock/>
 <CrowdPricingPanel data={a.crowdPricing}/>
 <Section title="Empirical read"><MetricGrid items={a.returns.map(r=>({label:r.label,value:pct(r.value),tone:(r.value??0)>=0?"pos":"neg"}))}/></Section>

 {a.walkForward&&<WalkForwardAudit data={a.walkForward} symbol={a.instrument.symbol}/>}\n </details></>}

type CycleOverlayData=ApiResponse<typeof api,"getHistoricalContext">["cycleOverlay"];
function CycleOverlay({data}:{data:CycleOverlayData}){const series=data.meaningful?[{label:"CURRENT",values:data.current.values,current:true},...data.analogs.map((row,index)=>({label:`ANALOG ${index+1} · ${row.startDate}`,values:row.values,current:false}))]:[];const all=series.flatMap(row=>row.values),min=all.length?Math.min(...all):90,max=all.length?Math.max(...all):110,range=Math.max(1,max-min);const path=(values:number[])=>values.map((value,index)=>`${index?"L":"M"} ${(index/(Math.max(1,values.length-1))*100).toFixed(2)} ${(100-(value-min)/range*100).toFixed(2)}`).join(" ");return <div className="cycle-detection"><div className="cycle-score"><div><span className="eyebrow">252-SESSION NORMALIZED PATTERN TEST</span><b>{data.meaningful?"STATISTICAL MATCH FOUND":"NO MEANINGFUL PATTERN FOUND"}</b></div><div><span>Best correlation {data.topCorrelation==null?"—":num(data.topCorrelation,3)}</span><span>Similarity z-score {data.similarityZ==null?"—":num(data.similarityZ,2)}</span><span>{data.sampleCount} historical windows tested</span></div></div>{data.meaningful?<><div className="cycle-chart"><svg viewBox="0 0 100 100" role="img" aria-label="Normalized current 252-session path overlaid against three statistically selected historical analogs" preserveAspectRatio="none"><line x1="0" y1={(100-(100-min)/range*100)} x2="100" y2={(100-(100-min)/range*100)} className="cycle-zero"/>{series.map((row,index)=><path key={row.label} d={path(row.values)} className={row.current?"cycle-current":`cycle-analog a${index}`}/>)}</svg></div><div className="cycle-legend">{series.map(row=><span key={row.label} className={row.current?"current":""}>{row.label}</span>)}</div></>:<div className="empty">The chart is withheld because the best match did not clear both correlation ≥ {num(data.similarityThreshold,2)} and z-score ≥ 2. Decorative cycle lines would imply an edge that the history did not show.</div>}<div className={`cycle-divergence ${data.divergence}`}><b>{data.divergence==="breaking"?"DIVERGENCE FLAG":data.divergence==="none"?"PATTERN INTACT":"NO DIVERGENCE TEST"}</b><span>{data.divergenceNote}</span></div><details><summary>METHOD + INPUTS</summary><p>{data.method}</p><p>Fit: first {data.fitSessions} sessions · full window: {data.horizonSessions} sessions · adjusted closes normalized to 100.</p>{data.analogs.map(row=><p key={row.startDate}>{row.startDate} → {row.endDate} · r {num(row.correlation,3)} · post-fit {pct(row.postFitReturnPct)}</p>)}</details></div>}
function UnderwaterChart({rows}:{rows:Array<{date:string;drawdownPct:number}>}){if(!rows.length)return <div className="empty">Underwater history unavailable.</div>;const path=rows.map((row,index)=>`${index?"L":"M"} ${(index/(Math.max(1,rows.length-1))*100).toFixed(2)} ${Math.max(0,Math.min(100,-row.drawdownPct)).toFixed(2)}`).join(" ");return <div className="underwater"><svg viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-label="Full-history underwater drawdown chart"><line x1="0" x2="100" y1="0" y2="0"/><path d={path}/></svg><div><span>{rows[0]?.date}</span><b>0% = prior high · depth plotted downward</b><span>{rows.at(-1)?.date}</span></div></div>}
function CycleClock(){const q=useQuery({queryKey:["cycle-clock"],queryFn:()=>api.getCycleClock({}),staleTime:24*60*60*1000});return <Section title="Cycle clock · growth × inflation transmission">{q.isPending?<LoadingSkeleton label="Reading cached macro proxies"/>:q.error?<div className="error">Cycle clock unavailable: {String(q.error)}</div>:q.data?.status==="unavailable"?<div className="empty"><b>NO REGIME CLASSIFICATION</b><p>{q.data.note}</p><small>Missing cached inputs: {q.data.missingSymbols.join(", ")||"overlap unavailable"}</small></div>:q.data&&<><div className={`cycle-phase ${q.data.phase}`}><span>CURRENT PHASE · {q.data.asOf}</span><b>{q.data.phase?.toUpperCase()}</b></div><div className="regime-ribbon" aria-label="Historical cycle-clock regime ribbon">{q.data.ribbon.map((row,index)=><span key={`${row.date}-${index}`} className={row.phase} title={`${row.date} · ${row.phase}`}/>)}</div><div className="transmission-chain">{q.data.chain.map((row,index)=><div key={row.input}><span>{index+1}</span><div><b>{row.input} · {row.reading}</b><p>{row.effect}</p></div></div>)}</div><p className="subline">{q.data.note}</p></>}</Section>}
function HistoricalContext({symbol,currency}:{symbol:string;currency:string|null}){const q=useQuery({queryKey:["historical-context",symbol],queryFn:()=>api.getHistoricalContext({symbol}),staleTime:24*60*60*1000});return <Section title="Full-history cycle context">{q.isPending?<LoadingSkeleton label="Loading cached full-history context"/>:q.error?<div className="error">Historical context unavailable: {String(q.error)}</div>:q.data&&<><div className="history-meta"><b>{q.data.firstDate} → {q.data.lastDate}</b><span>{num(q.data.sessions,0)} daily sessions · {q.data.currency??currency??"currency unavailable"} · cached {new Date(q.data.fetchedAt).toLocaleString()}</span><a href={q.data.sourceUrl} target="_blank" rel="noreferrer">YAHOO CHART SOURCE</a></div><div className="notice base-rate">{q.data.basisNote}</div><CycleOverlay data={q.data.cycleOverlay}/><Section title="Timeframe ladder · trend / momentum / volume"><div className="timeframe-ladder">{q.data.timeframeLadder.map(row=><div key={row.label}><b>{row.label}</b><span className={row.trend==="up"?"pos":row.trend==="down"?"neg":""}>trend {row.trend}</span><span className={row.momentum==="up"?"pos":row.momentum==="down"?"neg":""}>momentum {row.momentum}</span><span>volume {row.volume}</span><strong className={row.votes>0?"pos":row.votes<0?"neg":""}>{row.votes>0?"+":""}{row.votes}/3</strong><small>{row.detail}</small></div>)}</div></Section><Section title="Full-history underwater chart"><UnderwaterChart rows={q.data.underwater}/></Section><div className="distribution-grid">{q.data.distributions.map(metric=><div className="distribution" key={metric.label}><div><span>{metric.label}</span><b>{metric.value==null?"Unavailable":`${num(metric.value)}${metric.unit==="%"?"%":""}`}</b></div><div className="distribution-track" aria-label={`${metric.label} full-history percentile`}><span style={{width:`${Math.max(0,Math.min(100,metric.percentile??0))}%`}}/></div><small>{metric.percentile==null?"Percentile unavailable":`${num(metric.percentile,1)}th percentile of available history`}</small></div>)}</div><Section title={`Drawdown anatomy · every 20%+ decline (${q.data.drawdowns.length})`}><div className="history-table">{q.data.drawdowns.length?q.data.drawdowns.map((row,index)=><div className="history-row" key={`${row.peakDate}-${index}`}><div><b>{row.peakDate} → {row.bottomDate}</b><small>{row.recoveryDate?`Recovered ${row.recoveryDate}`:"Not recovered in cached history"}</small></div><strong className="neg">{pct(row.depthPct)}</strong><span>{row.declineSessions} sessions down · {row.recoverySessions==null?"recovery open":`${row.recoverySessions} sessions to recover`}</span><span>Bottom RSI {num(row.bottomRsi14)} · vs SMA-200 {pct(row.bottomVsSma200Pct)} · next 90 sessions {pct(row.forward90dPct)}</span></div>):<div className="empty">No 20% drawdown exists in the available adjusted-close history.</div>}</div></Section><div className="history-split"><Section title="Five nearest historical analogs"><div className="history-table">{q.data.analogs.map(row=><div className="history-row compact" key={row.date}><div><b>{row.date}</b><small>feature distance {num(row.distance)}</small></div><strong className={(row.forward90dPct??0)>=0?"pos":"neg"}>{pct(row.forward90dPct)} / next 90 sessions</strong><span>RSI {num(row.rsi14)} · volume pctl {num(row.volumePercentile)} · volatility pctl {num(row.volatilityPercentile)}</span></div>)}</div></Section><Section title={`Cycle highs / lows · ${q.data.currency??currency??"currency unavailable"}`}><div className="history-table">{q.data.cycleYears.map(row=><div className="history-row compact" key={row.year}><div><b>{row.year}</b><small>{row.lowDate} low · {row.highDate} high</small></div><strong>{quoteMoney(row.low,q.data.currency??currency)} → {quoteMoney(row.high,q.data.currency??currency)}</strong><span>Year return {pct(row.yearReturnPct)}</span></div>)}</div></Section></div></>}</Section>}

function _CompletePicture({symbol,name}:{symbol:string;name:string}){
 const q=useQuery({queryKey:["complete-picture",symbol],queryFn:()=>api.getDossierSynthesis({symbol,name}),staleTime:5*60*1000});
 const sourceJobs=useQuery({queryKey:["source-jobs"],queryFn:()=>api.getSourceJobs({}),staleTime:5*60*1000});
 const [open,setOpen]=useState<Record<string,boolean>>({direction:true,signals:true,news:true,smart_money:true,theories:true,competition:true,sector:true,supply_chain:true,macro:true,risks:true});
 if(q.isPending)return <section className="complete-picture loading-picture" aria-label={`Building ${symbol} Complete Picture`}><div className="picture-kicker"><span>COMPLETE PICTURE</span><b>Building the Complete Picture…</b></div><LoadingSkeleton label="Reading factors, outcomes, news, filings, theories, peers, macro"/></section>;
 if(q.error)return <section className="complete-picture"><div className="error">Complete Picture failed: {String(q.error)}</div></section>;
 const data=q.data;if(!data)return null;const sourceMap=new Map(data.sources.map(source=>[source.id,source]));
 return <section className={`complete-picture ${data.status}`} aria-label={`${symbol} Complete Picture`}>
  <header className="picture-head"><div><span className="eyebrow">COMPLETE PICTURE · {data.status.toUpperCase()}</span><h2>{data.headline}</h2><p>{data.summary}</p></div><div className={`picture-calibration ${data.calibration.label==="MEASURED"?"measured":"uncalibrated"}`}><small>LIVE CALL RELIABILITY</small><b>{data.calibration.label}</b><span>{data.calibration.note}</span></div></header>
  {data.keyTension&&<div className="picture-tension"><small>CENTRAL TENSION</small><p>{data.keyTension}</p></div>}
  <div className="picture-sections">{data.sections.map(section=><article className={`picture-lane ${section.state}`} key={section.key}><button className="picture-lane-head" onClick={()=>setOpen(current=>({...current,[section.key]:!current[section.key]}))} aria-expanded={open[section.key]??false}><span><small>{section.state==="available"?`${section.claims.length} TRACEABLE ${section.claims.length===1?"READ":"READS"}`:"NO DATA"}</small><b>{section.title}</b></span><i aria-hidden="true">{open[section.key]?"−":"+"}</i></button>{open[section.key]&&<div className="picture-lane-body">{section.claims.length?section.claims.map((claim,index)=><div className="picture-claim" key={`${section.key}-${index}`}><p>{claim.text}</p><div className="picture-refs">{claim.sourceIds.map(sourceId=>{const source=sourceMap.get(sourceId);if(!source)return null;return source.url?<a key={sourceId} href={source.url} target="_blank" rel="noreferrer">[{sourceId}] {source.title}</a>:<span key={sourceId}>[{sourceId}] {source.title}</span>})}</div></div>):<div className="picture-empty">{section.note}</div>}</div>}</article>)}</div>
  {data.gaps.length>0&&<details className="picture-gaps"><summary>DATA GAPS · {data.gaps.length}</summary>{data.gaps.map((gap,index)=><p key={index}>{gap}</p>)}</details>}
  <details className="picture-sources"><summary>SOURCE LEDGER · {data.sources.length}</summary><div>{data.sources.map(source=>source.url?<a key={source.id} href={source.url} target="_blank" rel="noreferrer"><b>[{source.id}] {source.title}</b><span>{source.kind} · {source.asOf?asOfLabel(source.asOf):"date unavailable"}</span></a>:<article key={source.id}><b>[{source.id}] {source.title}</b><span>{source.kind} · {source.asOf?asOfLabel(source.asOf):"date unavailable"}</span></article>)}</div></details>
  <details className="picture-sources"><summary>SOURCE JOBS · {sourceJobs.data?.jobs.length??0}</summary><div>{sourceJobs.data?.jobs.map(job=><article key={job.source}><b>{job.source} · {job.job}</b><span>{job.quota.used==null?"usage not exposed":`${job.quota.used} used`} / {job.quota.cap==null?"uncapped or unknown":job.quota.cap}</span></article>)??<span>Source job map unavailable.</span>}</div></details>
  <footer>Generated {asOfLabel(data.generatedAt)} · Every read points to the market source, filing, news item, theory evidence, or frozen terminal record beneath it. No paid-flow metrics are inferred.</footer>
 </section>
}
type WatchItem=ApiResponse<typeof api,"scanWatchlist">["items"][number];
function WatchRow({x,choose,remove}:{x:WatchItem;choose:(q:string)=>void;remove:(id:number)=>void}){return <div className="watch-row"><div className="row"><button className="row-link" onClick={()=>choose(x.symbol)}><h4>{x.symbol} · {x.name}</h4><p>{x.error??`${money(x.price)} · ${pct(x.changePercent)} · ${x.label}`}</p></button><div className="watch-actions"><button className="secondary danger" aria-label={`Remove ${x.symbol} from watchlist`} onClick={()=>remove(x.id)}>×</button></div></div>{x.signalScore!=null&&x.factors.length?<div className="watch-rating"><b className={x.signalScore>0?"pos":x.signalScore<0?"neg":""}>{x.signalScore>0?"+":""}{x.signalScore} · {x.direction?directionLabel(x.direction):"DIRECTION UNAVAILABLE"}</b><Reliability score={x.signalScore}/><div className="signal-safeguards"><span className={isStale(x.sourceAsOf)?"stale":"fresh"}>{isStale(x.sourceAsOf)?"STALE":"FRESH"}</span><span>As of {asOfLabel(x.sourceAsOf)}</span><span>Invalidation {money(x.invalidationLevel)}</span>{x.sourceUrl?<a href={x.sourceUrl} target="_blank" rel="noreferrer">Evidence / disconfirmation source</a>:<span>Evidence link unavailable</span>}</div><details className="factor-disclosure"><summary>FACTOR BREAKDOWN</summary><small>{x.formula}</small>{x.factors.map(factor=><div className="factor-row" key={factor.name}><span><b>{factor.name}</b><small>{factor.reading}</small></span><span>w {num(factor.weight,3)} × {factor.score>0?"+":""}{factor.score} = <b className={factor.contribution>0?"pos":factor.contribution<0?"neg":""}>{factor.contribution>0?"+":""}{num(factor.contribution,3)}</b></span></div>)}</details></div>:x.signalScore!=null?<div className="notice">Legacy rating omitted: factor evidence was not retained.</div>:null}</div>}
function Watchlist({choose,qc}:{choose:(q:string)=>void;qc:ReturnType<typeof useQueryClient>}){const q=useQuery({queryKey:["watchlist"],queryFn:()=>api.scanWatchlist({})});const del=useMutation({mutationFn:(id:number)=>api.removeWatch({id}),onSuccess:()=>qc.invalidateQueries({queryKey:["watchlist"]})});return <><Section title="Watchlist dashboard" right={<button className="secondary" onClick={()=>q.refetch()} disabled={q.isFetching}>{q.isFetching?"SCANNING…":"REFRESH"}</button>}><div className="notice">{q.data?.note??"Scanning watched names through Yahoo Finance…"}</div><div className="list panel">{q.isPending?<div className="empty">SCANNING…</div>:q.data?.items.length?q.data.items.map(x=><WatchRow key={x.id} x={x} choose={choose} remove={id=>del.mutate(id)}/>):<div className="empty">No watched instruments. Analyze one and tap + WATCH.</div>}</div></Section></>}
function Scorecard(){
 const q=useQuery({queryKey:["scorecard"],queryFn:()=>api.getScorecard({})});
 if(q.isPending)return <Section title="Scorecard"><LoadingSkeleton label="Loading machine report card"/></Section>;
 if(q.error)return <Section title="Scorecard"><div className="error">Scorecard failed: {String(q.error)}</div></Section>;
 const d=q.data,record=d.trackRecord;
 return <Section title="Scorecard · is the machine any good?">
  <div className="scorecard" aria-label="Read-only machine scorecard">
   <section className="scorecard-lane track-record">
    <div className="scorecard-lane-head"><span>01</span><div><b>Track record</b><small>Independent first-touch grading</small></div></div>
    <div className="scorecard-kpis"><div><small>TRACKED</small><b>{record.tracked}</b></div><div><small>GRADED CLOSED</small><b>{record.gradedClosed}</b></div><div><small>OPEN</small><b>{record.open}</b></div><div><small>HIT RATE</small><b>{record.hits}/{record.gradedClosed} · {record.hitRate==null?"—":`${num(record.hitRate)}%`}</b><span>{record.sampleNote}</span></div></div>
    <div className="scorecard-splits"><div><small>BY DIRECTION</small>{record.byDirection.map(row=><p key={row.label}><span>{row.label.toUpperCase()}</span><b>{row.hits}/{row.closed}</b></p>)}</div><div><small>BY SCORE BAND</small>{record.byScoreBand.map(row=><p key={row.label}><span>{row.label}</span><b>{row.hits}/{row.closed}</b></p>)}</div><div><small>EXCLUDED FROM DENOMINATOR</small><p><span>AMBIGUOUS</span><b>{record.excluded.ambiguous}</b></p><p><span>STALE</span><b>{record.excluded.stale}</b></p><p><span>UNVERIFIED</span><b>{record.excluded.unverified}</b></p></div></div>
   </section>
   <section className="scorecard-lane">
    <div className="scorecard-lane-head"><span>02</span><div><b>Expectancy</b><small>Net R versus buy-and-hold and random-entry baselines</small></div></div>
    <div className="scorecard-state collecting"><b>COLLECTING</b><p>{d.expectancy.note}</p><small>Estimate begins at 10 independently graded closes · future comparisons are net of {d.expectancy.costBps} bps costs.</small></div>
   </section>
   <section className="scorecard-lane">
    <div className="scorecard-lane-head"><span>03</span><div><b>Runner recall</b><small>Caught ÷ total runners · fast and slow windows</small></div></div>
    <div className="scorecard-state"><b>NO LIVE RUNS YET</b><p>{d.runnerRecall.note}</p><small>{d.runnerRecall.dryRunNote}</small></div>
   </section>
   <section className="scorecard-lane">
    <div className="scorecard-lane-head"><span>04</span><div><b>Calibration status</b><small>Observed outcomes, not a converted formula</small></div></div>
    <div className="scorecard-state collecting"><b>COLLECTING</b><p>{d.calibration.note}</p></div>
   </section>
   <footer className="scorecard-honesty"><div><b>05 · Honesty ledger</b><p>{d.honesty.note}</p><small>{d.honesty.exclusionSummary}</small></div><div className="scorecard-sources">{d.honesty.sources.map(source=><span key={source.label}>{source.label} · {asOfLabel(source.asOf)}</span>)}<strong>Card as of {asOfLabel(d.honesty.asOf)}</strong></div></footer>
  </div>
 </Section>
}

function SuppressedSignalLog(){const q=useQuery({queryKey:["suppressed-signal-candidates"],queryFn:()=>api.listSuppressedSignalCandidates({limit:25})});return <Section title="Suppressed candidates" right={q.data?<span className="eyebrow">{q.data.total} LOGGED</span>:undefined}><p className="subline">Candidates stopped before publication. Born-dead levels and short-regime failures never enter the tracked-signal record.</p>{q.isPending?<div className="loading">LOADING SUPPRESSION LOG…</div>:q.error?<div className="error">Suppression log failed: {String(q.error)}</div>:q.data.candidates.length?<div className="suppressed-list">{q.data.candidates.map(candidate=><article className="suppressed-row" key={candidate.id}><div className="suppressed-main"><div><h4>{candidate.symbol} · {directionLabel(candidate.direction)}</h4><p>{dateLabel(candidate.signalDate)} · {candidate.setupType} · {candidate.origin}</p></div><span className="status refuted">SUPPRESSED</span></div><strong>{candidate.reason}</strong><div className="snapshot-line"><span>entry {money(candidate.entryPrice)}</span><span>invalidation {money(candidate.invalidationLevel)}</span><span>signal-day open {money(candidate.signalDayOpen)}</span><span>high {money(candidate.signalDayHigh)}</span><span>low {money(candidate.signalDayLow)}</span><span>close {money(candidate.signalDayClose)}</span>{candidate.direction==="short"&&<span>below SMA-50 {candidate.context.belowSma50==null?"—":candidate.context.belowSma50?"yes":"no"}</span>}</div>{candidate.sourceUrl?<a href={candidate.sourceUrl} target="_blank" rel="noreferrer">Signal-day series</a>:<small>Source link unavailable</small>}</article>)}</div>:<div className="empty">No candidate has been suppressed yet.</div>}</Section>}
function Tracker({openTape}:{openTape:(q:string)=>void}){const qc=useQueryClient();const q=useQuery({queryKey:["tracker"],queryFn:()=>api.getSignalTracker({})});const run=useMutation({mutationFn:()=>api.runDailySignalPostmortem({}),onSuccess:()=>qc.invalidateQueries({queryKey:["tracker"]})});if(q.isPending)return <div className="loading">SCORING SIGNALS…</div>;if(q.error)return <div className="error">Signal tracker failed: {String(q.error)}</div>;const openSignals=q.data.signals.filter(x=>!x.tradeSetupEvaluation||x.tradeSetupEvaluation.verdict==="OPEN");return <><Section title="Daily post-mortem" right={<button className="secondary" onClick={()=>run.mutate()} disabled={run.isPending}>{run.isPending?"CHECKING PRICES…":"RUN CHECK NOW"}</button>}><div className="postmortem"><div className="postmortem-copy"><span className="eyebrow">TRACKING, NOT A VERDICT</span><p>{run.data?.summary??q.data.latestBrief?.summary??"No daily snapshot has been recorded yet. Run the check to append today’s market-price snapshot to each open signal."}</p>{run.data?.errors.length?<small>{run.data.errors.join(" · ")}</small>:q.data.latestBrief?<small>Market data through {asOfLabel(q.data.latestBrief.sourceAsOf)} · recorded {dateLabel(q.data.latestBrief.capturedDay)}</small>:null}</div><div className="postmortem-metrics"><div><small>TRACKED SIGNALS</small><b>{run.data?.trackedCount??q.data.latestBrief?.trackedCount??0}</b></div><div><small>NEAR TARGET 1 (TRACKED PLAN) · ≤3%</small><b>{run.data?.approachingTargetCount??q.data.latestBrief?.approachingTargetCount??0}</b></div><div><small>NEAR INVALIDATION · ≤3%</small><b>{run.data?.approachingInvalidationCount??q.data.latestBrief?.approachingInvalidationCount??0}</b></div></div></div></Section><Section title="Versioned direction outcomes"><p className="subline">One fixed 30-session direction forecast cohort. Returns are gross; unknown costs are never presented as net.</p><div className="metric-grid">{q.data.stats.length?q.data.stats.map(x=><div className={`metric ${x.killSuggested?"kill-flag":""}`} key={`${x.setupType}-${x.agreementBand}`}><small>{x.setupType} · {x.agreementBand}</small><b className={x.expectancy>=0?"pos":"neg"}>{pct(x.avgReturn)} average gross</b><span className="subline">{num(x.hitRate)}% direction hits · avg positive {pct(x.avgWin)} · avg non-positive {pct(x.avgLoss)} · costs unknown</span></div>):<div className="empty wide">No accepted 30-session direction evaluations in a matching cohort yet.</div>}</div></Section><Section title="Open paper setups"><p className="subline">Issued {q.data.outcomeCounts.issued} · open {q.data.outcomeCounts.open} · resolved {q.data.outcomeCounts.resolved} · ambiguous {q.data.outcomeCounts.ambiguous} · unverified {q.data.outcomeCounts.unverified}. Setup first-touch and fixed-horizon direction are separate products.</p><div className="tracked-signal-list">{openSignals.length?openSignals.map(x=>{const checkpoint=(day:number)=>x.history.find(snapshot=>snapshot.daysSinceEntry===day);const one=checkpoint(1),two=checkpoint(2),three=checkpoint(3),latest=x.history.at(-1);return <article className="tracked-signal" key={x.id}><button className="row-link tracked-signal-open" onClick={()=>openTape(x.symbol)} aria-label={`Open ${x.symbol} signal tape`}><div><h4>{x.symbol} · {x.setupType}</h4><p>{x.signalDate} · {directionLabel(x.direction)} · {x.factors.length?`${x.signalScore>0?"+":""}${x.signalScore}/100 factor agreement · `:"rating omitted · "}entry {money(x.entryPrice)}</p></div><small>OPEN TAPE</small></button><div className="review-strip"><div className="review-group tracking"><b>TRACKING-IN-PROGRESS</b><span>1D {pct(one?.returnPct)}</span><span>2D {pct(two?.returnPct)}</span><span>3D {pct(three?.returnPct)}</span></div><div className="review-group verdict"><b>VERSIONED EVALUATIONS</b><span>Setup {x.tradeSetupEvaluation?.verdict??"OPEN"}</span><span>Direction {x.directionEvaluation?.verdict??"OPEN"}</span><span>30-session gross {pct(x.directionEvaluation?.grossReturnPct)}</span></div></div>{latest&&<div className="snapshot-line"><span>Latest {money(latest.currentPrice)}</span><span>{pct(latest.returnPct)} since entry</span><span>{pct(latest.distanceTarget1Pct)} to tracked target 1</span><span>{pct(latest.distanceInvalidationPct)} invalidation cushion</span><span>day {latest.daysSinceEntry}</span></div>}<div className="signal-safeguards"><span className={isStale(x.sourceAsOf)?"stale":"fresh"}>{isStale(x.sourceAsOf)?"STALE":"FRESH"}</span><span>Source as of {asOfLabel(x.sourceAsOf)}</span><span>{x.barState==="forming"?"FORMING BAR":"CLOSED BAR"} · {asOfLabel(x.barTimestamp)}</span><span>Target 1 (1.5R mechanical) {money(x.target1)}</span><span>Invalidation {money(x.invalidationLevel)}</span>{x.sourceUrl?<a href={x.sourceUrl} target="_blank" rel="noreferrer">Evidence / disconfirmation source</a>:<span>Evidence link unavailable</span>}</div><div className={`invalidation-read ${x.tightInvalidation===true?"tight":x.roomToBreatheAtr==null?"unavailable":"clear"}`}>{x.roomToBreatheAtr==null?<><b>ATR-14 UNAVAILABLE</b><span>{x.invalidationLevel==null?"Invalidation level is unavailable; geometry is withheld.":"Signal-date daily OHLC was unavailable; geometry is withheld."}</span></>:<><b>{x.invalidationGrade}</b><span><strong>{num(x.roomToBreatheAtr,2)}× ATR</strong> room to breathe</span><span>{x.invalidationMethod??"LEGACY ISSUED LEVEL · preserved unchanged"}</span><span>{x.invalidationAtr14!=null&&x.invalidationAtrMultiple!=null?`Issued with ATR-14 ${money(x.invalidationAtr14)} at ${num(x.invalidationAtrMultiple,2)}×`:"Current ATR ratio is diagnostic only; the issued level was not rewritten."}</span><span>{x.tightInvalidation?"TIGHT INVALIDATION · STOP-HUNT ZONE":"Outside the <0.75× ATR stop-hunt zone"}</span></>}</div>{x.factors.length?<><Reliability score={x.signalScore}/><details className="factor-disclosure"><summary>FACTOR BREAKDOWN</summary><small>{x.formula}</small>{x.factors.map(factor=><div className="factor-row" key={factor.name}><span><b>{factor.name}</b><small>{factor.reading}</small></span><span>w {num(factor.weight,3)} × {factor.score>0?"+":""}{factor.score} = <b className={factor.contribution>0?"pos":factor.contribution<0?"neg":""}>{factor.contribution>0?"+":""}{num(factor.contribution,3)}</b></span></div>)}</details></>:<div className="notice">Rating omitted: factor history was not retained for this legacy signal. Open the tape to recompute it.</div>}</article>}):<div className="empty">No setups are currently open. Ambiguous and unverified records remain visible in the scorecard counts.</div>}</div></Section><SuppressedSignalLog/></>}
function Alerts({qc,choose}:{qc:ReturnType<typeof useQueryClient>;choose:(q:string)=>void}){const q=useQuery({queryKey:["alerts"],queryFn:()=>api.listAlerts({})});const scan=useMutation({mutationFn:()=>api.scanWatchlist({}),onSuccess:()=>{qc.invalidateQueries({queryKey:["alerts"]});qc.invalidateQueries({queryKey:["watchlist"]})}});return <><Section title="Alert feed" right={<button className="secondary" onClick={()=>scan.mutate()} disabled={scan.isPending}>{scan.isPending?"SCANNING…":"SCAN NOW"}</button>}><div className="notice">Radar 90+ scan hits, entry retests, RSI extremes, volume spikes, SEC Form 4 / 13D-G filings, and sourced upcoming earnings dates.</div><div className="list panel">{q.data?.alerts.length?q.data.alerts.map(x=><div className="row" key={x.id}><button className="row-link" onClick={()=>choose(x.symbol)} aria-label={`Open ${x.symbol} dossier from alert`}><h4>{x.symbol} · {x.kind}</h4><p>{x.message}</p><p>{new Date(x.createdAt).toLocaleString()} · OPEN DOSSIER</p></button>{x.sourceUrl&&<a href={x.sourceUrl} target="_blank" rel="noreferrer">SOURCE</a>}</div>):<div className="empty">No alerts yet. Add names to the watchlist, then scan.</div>}</div></Section></>}

type NewsItem = ApiResponse<typeof api,"getNews">["items"][number];
function News({symbol,qc}:{symbol:string;qc:ReturnType<typeof useQueryClient>}){const [view,setView]=useState<"symbol"|"discovery">(symbol?"symbol":"discovery");const theories=useQuery({queryKey:["theories"],queryFn:()=>api.listTheories({limit:20,cursor:null})});const [theoryId,setTheoryId]=useState("");const q=useQuery({queryKey:["news",view,symbol],queryFn:()=>api.getNews({scope:view==="symbol"?"coin":"discovery",symbol:view==="symbol"?symbol:"MARKET",limit:12,cursor:null})});const attach=useMutation({mutationFn:(x:{item:NewsItem;stance:"confirming"|"challenging"})=>api.attachTheoryEvidence({theoryId:Number(theoryId),stance:x.stance,title:x.item.title,source:x.item.source,url:x.item.url,publishedAt:x.item.publishedAt}),onSuccess:()=>qc.invalidateQueries({queryKey:["theories"]})});return <><Section title="News / discovery" right={<button className="secondary" onClick={()=>q.refetch()} disabled={q.isFetching}>{q.isFetching?"REFRESHING…":"REFRESH"}</button>}><div className="view-switch"><button className={view==="symbol"?"active":""} onClick={()=>setView("symbol")} disabled={!symbol}>{symbol?`${symbol} NEWS`:"SEARCH A SYMBOL"}</button><button className={view==="discovery"?"active":""} onClick={()=>setView("discovery")}>MARKET DISCOVERY</button></div><div className="notice">Every result links to its source. “Single-source” means the item has not been independently confirmed in this feed.</div>{theories.data?.theories.length?<div className="evidence-picker"><label htmlFor="evidence-theory">Attach news to theory</label><select id="evidence-theory" value={theoryId} onChange={e=>setTheoryId(e.target.value)}><option value="">Choose a theory…</option>{theories.data.theories.map(t=><option key={t.id} value={t.id}>{t.statement.slice(0,70)}</option>)}</select></div>:null}<div className="news-list">{q.isPending?<div className="empty">SEARCHING CURRENT SOURCES…</div>:q.error?<div className="error">News search failed: {String(q.error)}</div>:q.data?.items.length?q.data.items.map(item=><article className="news-item" key={item.id}><div className="news-meta"><span>{item.source}</span><time>{item.timestampKind==="published"?"Published":"Retrieved"} {new Date(item.publishedAt).toLocaleString()}</time></div><a href={item.url} target="_blank" rel="noreferrer"><h4>{item.title}</h4></a><p><b>Why it matters:</b> {item.whyItMatters}</p><div className="tag-row">{item.ripples.map(tag=><span className="badge" key={tag}>{tag}</span>)}<span className="badge unconfirmed">{item.confirmation}</span></div>{theoryId&&<div className="evidence-actions"><button className="secondary" onClick={()=>attach.mutate({item,stance:"confirming"})}>ATTACH AS CONFIRMING</button><button className="secondary danger" onClick={()=>attach.mutate({item,stance:"challenging"})}>ATTACH AS CHALLENGING</button></div>}</article>):<div className="empty">No current results were returned. Try Refresh.</div>}</div><p className="subline">Retrieved {q.data?new Date(q.data.retrievedAt).toLocaleString():"—"}</p></Section></>}

type TheoryRow = ApiResponse<typeof api,"listTheories">["theories"][number];
type TheoryForm = {id:number|null;statement:string;horizon:"short"|"long";tickers:string;predictions:string;ripples:string};
const emptyTheory:TheoryForm={id:null,statement:"",horizon:"short",tickers:"",predictions:"",ripples:""};
function parsePredictions(value:string){return value.split("\n").map(line=>line.split("|").map(x=>x.trim())).flatMap(parts=>{const ticker=parts[0]??"";const direction=parts[1]==="below"?"below" as const:parts[1]==="above"?"above" as const:null;const targetText=parts[2]??"";const dueDate=parts[3]??"";if(!ticker||!direction||!/^\d{4}-\d{2}-\d{2}$/.test(dueDate))return[];const parsed=targetText?Number(targetText):null;return[{ticker:ticker.toUpperCase(),direction,targetLevel:parsed!=null&&Number.isFinite(parsed)&&parsed>0?parsed:null,dueDate}]})}
function parseRipples(value:string){return value.split("\n").map(line=>line.split("|").map(x=>x.trim())).flatMap(parts=>{const from=parts[0]??"",to=parts[1]??"",because=parts.slice(2).join(" | ");return from&&to&&because?[{from,to,because}]:[]})}
function theoryToForm(t:TheoryRow):TheoryForm{return{id:t.id,statement:t.statement,horizon:t.horizon,tickers:t.linkedTickers.join(", "),predictions:t.predictions.map(p=>`${p.ticker} | ${p.direction} | ${p.targetLevel??""} | ${p.dueDate}`).join("\n"),ripples:t.ripples.map(r=>`${r.from} | ${r.to} | ${r.because}`).join("\n")}}
function UserTheories({qc}:{qc:ReturnType<typeof useQueryClient>}){const [view,setView]=useState<"short"|"long">("short");const [form,setForm]=useState<TheoryForm>(emptyTheory);const [formError,setFormError]=useState("");const q=useQuery({queryKey:["theories"],queryFn:()=>api.listTheories({})});const save=useMutation({mutationFn:()=>{const linkedTickers=[...new Set(form.tickers.split(",").map(x=>x.trim().toUpperCase()).filter(Boolean))];const predictions=parsePredictions(form.predictions);const ripples=parseRipples(form.ripples);if(!form.statement.trim()||!linkedTickers.length||!predictions.length)throw new Error("Add a statement, at least one linked ticker, and one valid prediction line.");return api.saveTheory({id:form.id,statement:form.statement.trim(),horizon:form.horizon,linkedTickers,predictions,ripples})},onSuccess:()=>{setForm(emptyTheory);setFormError("");qc.invalidateQueries({queryKey:["theories"]})},onError:e=>setFormError(String(e))});const del=useMutation({mutationFn:(id:number)=>api.deleteTheory({id}),onSuccess:()=>qc.invalidateQueries({queryKey:["theories"]})});const rows=(q.data?.theories??[]).filter(t=>t.horizon===view);return <><Section title={form.id?"Update theory":"Create a falsifiable theory"}><form className="form panel" onSubmit={e=>{e.preventDefault();save.mutate()}}><div className="field"><label htmlFor="theory-statement">Plain statement</label><textarea id="theory-statement" required value={form.statement} onChange={e=>setForm({...form,statement:e.target.value})} placeholder="A testable claim about what should happen and why."/></div><div className="form-grid"><div className="field"><label htmlFor="theory-horizon">Horizon</label><select id="theory-horizon" value={form.horizon} onChange={e=>setForm({...form,horizon:e.target.value as "short"|"long"})}><option value="short">Short-term · under 30 days</option><option value="long">Long-term</option></select></div><div className="field"><label htmlFor="theory-tickers">Linked tickers</label><input id="theory-tickers" value={form.tickers} onChange={e=>setForm({...form,tickers:e.target.value})} placeholder="META, XLK, QQQ"/></div></div><div className="field"><label htmlFor="theory-predictions">Predictions · one per line</label><textarea id="theory-predictions" value={form.predictions} onChange={e=>setForm({...form,predictions:e.target.value})} placeholder="META | above | 800 | 2026-12-31&#10;XLK | below |  | 2026-11-15"/><small className="subline">Format: TICKER | above or below | optional target level | YYYY-MM-DD</small></div><div className="field"><label htmlFor="theory-ripples">Ripple map · one per line</label><textarea id="theory-ripples" value={form.ripples} onChange={e=>setForm({...form,ripples:e.target.value})} placeholder="META | XLK | stronger ad growth can lift sector sentiment"/><small className="subline">Format: X | Y | because…</small></div>{formError&&<div className="error">{formError}</div>}<div className="form-actions"><button className="action" disabled={save.isPending}>{save.isPending?"SNAPSHOTTING PRICES…":form.id?"UPDATE THEORY":"CREATE + SNAPSHOT"}</button>{form.id&&<button type="button" className="secondary" onClick={()=>setForm(emptyTheory)}>CANCEL</button>}</div></form></Section><Section title="Tracked theories" right={<button className="secondary" onClick={()=>q.refetch()} disabled={q.isFetching}>{q.isFetching?"UPDATING…":"REFRESH PRICES"}</button>}><div className="view-switch"><button className={view==="short"?"active":""} onClick={()=>setView("short")}>SHORT-TERM</button><button className={view==="long"?"active":""} onClick={()=>setView("long")}>LONG-TERM</button></div><div className="theory-list">{q.isPending?<div className="empty">LOADING THEORIES…</div>:rows.length?rows.map(t=><article className="theory-card" key={t.id}><div className="theory-head"><div className="tag-row"><span className="badge machine-label">MUSE THEORY</span><span className={`status ${t.status}`}>{t.status}</span></div><span className="subline">Created {new Date(t.createdAt).toLocaleDateString()}</span></div><div className="memo-kicker">WRITTEN THESIS MEMO · {t.horizon.toUpperCase()} HORIZON</div><div className="memo-block"><b>THESIS</b><h4>{t.statement}</h4></div><div className="tag-row">{t.linkedTickers.map(x=><span className="badge" key={x}>{x} @ {money(t.snapshots[x])}</span>)}</div><div className="memo-block"><b>WHY</b><p className="subline">{t.predictions.map(p=>p.detail).join(" · ")}</p></div><div className="prediction-list">{t.predictions.map(p=><div className="prediction" key={p.id}><div><b>{p.ticker} · {p.direction.toUpperCase()} {p.targetLevel??"creation price"}</b><p>{p.detail}</p></div><div><span className={`status ${p.status}`}>{p.status}</span><small>{p.progress==null?"—":`${num(p.progress)}% progress`}</small></div></div>)}</div>{t.ripples.length?<div className="ripple-map"><b className="mini-head">OVERLAPS</b>{t.ripples.map(r=><div key={r.id}><b>{r.from} → {r.to}</b><span>{r.because}</span></div>)}</div>:null}<div className="memo-block"><b>KILL CONDITIONS / INVALIDATION LEVELS</b><p className="subline">{t.predictions.map(p=>`${p.ticker} ${p.direction} ${p.targetLevel??"creation price"} by ${p.dueDate}`).join(" · ")}</p></div>{t.evidence.length?<div className="evidence-list"><b>PRIMARY EVIDENCE LINKS</b>{t.evidence.map(e=><a key={`${e.kind}-${e.id}`} href={e.url} target="_blank" rel="noreferrer"><span className={`status ${e.stance==="confirming"?"confirming":e.stance==="challenging"?"challenged":"neutral"}`}>{e.stance}</span><span>{e.title} · {e.source}{e.kind==="sentiment"?` · ${e.publisher} · ticker ${num(e.tickerScore)} (${e.tickerLabel}) · overall ${num(e.overallScore)} (${e.overallLabel}) · as of ${new Date(e.asOf??e.createdAt).toLocaleString()} · SENTIMENT / ZERO SCORE WEIGHT`:""}</span></a>)}</div>:null}<div className="form-actions"><button className="secondary" onClick={()=>setForm(theoryToForm(t))}>EDIT</button><button className="secondary danger" onClick={()=>del.mutate(t.id)}>DELETE</button></div></article>):<div className="empty">No {view==="short"?"short-term":"long-term"} theories yet.</div>}</div><p className="subline">Status is recomputed from current Yahoo prices when this view loads or refreshes. A missed due-date prediction is refuted; in-progress movement in the expected direction is confirming; other live paths are challenged.</p></Section></>}

type MachineTheory = ApiResponse<typeof api,"listMachineTheories">["theories"][number];
type SocialChatter = ApiResponse<typeof api,"getSocialChatter">;
function Theories({qc,choose}:{qc:ReturnType<typeof useQueryClient>;choose:(q:string)=>void}){
 const [mode,setMode]=useState<"machine"|"mine"|"hits">("machine");
 const machine=useQuery({queryKey:["machine-theories"],queryFn:()=>api.listMachineTheories({}),staleTime:5*60*1000});
 const socialItems=(machine.data?.theories??[]).map(theory=>({ticker:theory.primarySymbol,theoryDirection:theory.directionalPick}));
 const social=useQuery({queryKey:["social-chatter-bulk",...socialItems.map(item=>`${item.ticker}|${item.theoryDirection}`)],queryFn:()=>api.getSocialChatterBulk({items:socialItems}),enabled:socialItems.length>0,staleTime:5*60*1000});
 const discover=useMutation({mutationFn:()=>api.discoverTheories({})});
 return <><Section title="Theories" right={<div className="theory-actions"><button className="secondary" onClick={()=>discover.mutate()} disabled={discover.isPending}>{discover.isPending?"COLLECTING EVIDENCE…":"REFRESH EVIDENCE"}</button></div>}>
  <div className="view-switch theory-view-switch" aria-label="Theory views"><button className={mode==="machine"?"active":""} onClick={()=>setMode("machine")}>THEORY WATCH</button><button className={mode==="mine"?"active":""} onClick={()=>setMode("mine")}>MY SAVED THEORIES</button><button className={mode==="hits"?"active":""} onClick={()=>setMode("hits")}>DISCOVERY HITS</button></div>
  {mode==="machine"&&<><div className="theory-command"><div><b>Theory discovery runs every 12 hours</b><p>New candidates appear in Theory Watch. Each one leads with the interpreted thesis, causal overlap, countercase and observable invalidation.</p></div><div className="keyless-note"><b>Social chatter · Stocktwits + Reddit</b><span>X needs paid access and isn't included.</span><a href="https://paste.trade" target="_blank" rel="noreferrer">OPEN PASTE.TRADE LEADERBOARD</a></div></div>
  {machine.data?.run&&<div className={`run-state ${machine.data.run.status}`}><b>{machine.data.run.status.toUpperCase()}</b><span>{machine.data.run.note}</span><small>{machine.data.run.sourceCount} sources · {machine.data.run.candidateCount} candidates · {machine.data.run.surfacedCount} surfaced · {machine.data.run.withheldFloorCount} floor-withheld · {machine.data.run.contestedCount} contested · checked {new Date(machine.data.run.finishedAt).toLocaleString()}</small></div>}
  {discover.data&&<div className={`notice ${discover.data.status==="ok"?"pos":""}`}>{discover.data.note}</div>}
  <div className="machine-theory-list">{machine.isPending?<LoadingSkeleton label="Loading Muse theories"/>:machine.error?<div className="error">Theory Watch failed: {String(machine.error)}</div>:machine.data?.theories.length?machine.data.theories.map(theory=><MachineTheoryCard key={theory.id} theory={theory} choose={choose} social={social.data?.items.find(item=>item.ticker===theory.primarySymbol)?.data??null} socialPending={social.isPending}/>):<div className="empty">No theory currently meets the two-measured-layer evidence floor. Run discovery to refresh the weighted watch list.</div>}</div>
  <EventActionMap/>
  </>}
 </Section>{mode==="mine"&&<UserTheories qc={qc}/>} {mode==="hits"&&<EngineHits/>}</>
}
function TheoryPositioning({theory}:{theory:MachineTheory}){
 const p=theory.positioning;
 return <section className={`positioning-panel ${p.state}`} aria-label={`Positioning options for ${p.symbol}`}>
  <div className="positioning-head"><div><span>POSITIONING OPTIONS · NEVER FORCED</span><strong>{p.symbol} · {p.horizon.toUpperCase()} HORIZON</strong></div><b>{p.options.length?`${p.options.length} FIT${p.options.length===1?"":"S"}`:"NO POSITIONING"}</b></div>
  <div className="positioning-context"><div><span>Current close</span><strong>{money(p.currentPrice)}</strong></div><div><span>Volatility regime</span><strong>{p.volatility?`${p.volatility.regime.toUpperCase()} · ${num(p.volatility.percentile)}th pct`:"Unavailable"}</strong></div><div><span>History</span><strong>{p.barCount?`${num(p.barCount)} bars`:"Unavailable"}</strong></div><div><span>Coverage</span><strong>{p.firstBar&&p.lastBar?`${p.firstBar} → ${p.lastBar}`:"Unavailable"}</strong></div></div>
  {(p.supports.length||p.resistances.length||p.liquidityZones.length)?<div className="positioning-levels"><div><span>SUPPORT</span><strong>{p.supports.length?p.supports.map(row=>money(row.level)).join(" · "):"No clean level"}</strong><small>{p.supports.map(row=>`${money(row.level)}: ${row.basis} Last seen ${row.lastSeen}.`).join(" ")}</small></div><div><span>RESISTANCE</span><strong>{p.resistances.length?p.resistances.map(row=>money(row.level)).join(" · "):"No clean level"}</strong><small>{p.resistances.map(row=>`${money(row.level)}: ${row.basis} Last seen ${row.lastSeen}.`).join(" ")}</small></div><div><span>HISTORICAL LIQUIDITY ZONES</span><strong>{p.liquidityZones.length?p.liquidityZones.map(row=>`${money(row.low)}–${money(row.high)}`).join(" · "):"Unavailable"}</strong><small>High-volume price bins from full history; not live order-book or liquidation data.</small></div></div>:null}
  {p.options.length?<div className="positioning-options">{p.options.map(option=><article key={option.kind}><header><div><span>OPTION · {option.kind.toUpperCase()}</span><h5>{option.label}</h5></div><b>UNCALIBRATED</b></header><p>{option.fit}</p><div className="positioning-timeline"><span>TIMELINE</span><strong>{option.timeline}</strong></div>{option.kind==="futures"?<div className="positioning-grid"><div><span>AGGRESSIVE ENTRY</span><strong>{option.aggressiveEntry?`${money(option.aggressiveEntry.low)}–${money(option.aggressiveEntry.high)}`:"Not offered"}</strong><small>{option.aggressiveEntry?.basis}</small></div><div><span>PATIENT ENTRY</span><strong>{option.patientEntry?`${money(option.patientEntry.low)}–${money(option.patientEntry.high)}`:"Not offered"}</strong><small>{option.patientEntry?.basis??"A distinct deeper level was not present."}</small></div><div><span>INVALIDATION</span><strong className="neg">{money(option.invalidation)}</strong><small>{option.invalidationBasis}</small></div><div><span>TARGETS</span><strong className="pos">{option.targets.map(target=>money(target.level)).join(" · ")}</strong><small>{option.targets.map(target=>`${money(target.level)}: ${target.basis}.`).join(" ")}</small></div></div>:<><p className="spot-thesis">{option.thesis}</p><div className="dca-list">{option.tranches.map(row=><div key={row.tranche}><span>TRANCHE {row.tranche}</span><strong>{money(row.level)}</strong><small>{row.basis}</small></div>)}</div>{option.invalidation!=null&&<div className="spot-invalidation"><span>TECHNICAL INVALIDATION</span><strong>{money(option.invalidation)}</strong><small>{option.invalidationBasis}</small></div>}</>}</article>)}</div>:<div className="no-position-copy"><strong>NO POSITIONING</strong><p>{p.reason}</p></div>}
  <p className="positioning-method">{p.methodology} Source: {p.source??"full-history source unavailable"}. Every figure is a price-history calculation; none is a probability.</p>
 </section>
}
function MachineTheoryCard({theory,choose,social,socialPending}:{theory:MachineTheory;choose:(q:string)=>void;social:SocialChatter|null;socialPending:boolean}){
 return <article className={`machine-theory ${theory.status}`}><div className="theory-head"><div className="tag-row"><span className="badge machine-label">MACHINE CANDIDATE</span><span className={`status ${theory.status}`}>{theory.status}</span>{theory.sourceIntegrity==="single_source"?<span className="fork-label">SINGLE SOURCE</span>:<span className="status confirming">{theory.independentSourceCount} INDEPENDENT SOURCES</span>}{theory.status==="contested"&&<span className="fork-label">NO DIRECTIONAL PICK</span>}</div><time>{new Date(theory.checkedAt).toLocaleString()}</time></div><div className="memo-kicker">WRITTEN THESIS MEMO</div><h4>{theory.title}</h4><div className="memo-block"><b>THESIS</b><p className="theory-thesis">{theory.thesis}</p></div><div className="theory-meta"><span>{theory.domain}</span><span>{theory.horizon}</span><span>{theory.confidenceTier.toUpperCase()} evidence</span><span>{theory.weightedScore>=0?"+":""}{theory.weightedScore} weighted</span><span>{theory.supportLabel.toUpperCase()}</span><span>{theory.directionalPick==="none"?"NO PICK":theory.directionalPick.toUpperCase()}</span></div><div className={theory.sourceIntegrity==="multi_source"?"notice pos":"notice"}>{theory.integrityNote}</div><div className="theory-symbol-actions"><button className="secondary" onClick={()=>choose(theory.primarySymbol)}>OPEN {theory.primarySymbol} DOSSIER</button>{theory.rivalSymbol&&<button className="secondary" onClick={()=>choose(theory.rivalSymbol??"")}>OPEN {theory.rivalSymbol}</button>}</div><p className="confidence-note">{theory.confidenceNote}</p>
 <div className="layer-grid">{theory.layers.map(layer=><div className={`layer ${layer.verdict}`} key={layer.name}><div><b>{layer.name}</b><span>{layer.verdict} · w {layer.weight} · {layer.contribution>0?"+":""}{layer.contribution}</span></div>{layer.deduplicated&&<small className="dedup-note">{layer.deduplicationNote??"deduplicated (shared sources)"}</small>}<p>{layer.evidence}</p></div>)}</div>
 <TheoryPositioning theory={theory}/>
 {theory.status==="contested"&&<div className="fork"><b>CONTESTED FORK</b><div><p><strong>IF IT RESOLVES:</strong> {theory.causalChain[0]?.mechanism??theory.thesis}</p><p><strong>IF IT BREAKS:</strong> {theory.countercase}</p></div></div>}
 <div className="theory-columns"><div><b className="mini-head">Causal chain</b><ol className="hop-list">{theory.causalChain.map((hop,index)=><li className={hop.check==="broken"?"broken-hop":""} key={`${hop.from}-${hop.to}-${index}`}><div className="hop-head"><span className={`status ${hop.check==="pass"?"confirming":"refuted"}`}>{hop.check}</span><span className="badge">{hop.kind}</span></div><b>{hop.from} → {hop.to}</b><p>{hop.mechanism}</p>{hop.kind==="evidence"?<div className="hop-sources">{hop.evidence.map((source,i)=><a key={`${source.url}-${i}`} href={source.url} target="_blank" rel="noreferrer">{source.source} · {source.title}</a>)}</div>:<small className="subline">Inference — no source is claimed for this hop.</small>}</li>)}</ol></div><div><b className="mini-head">What may come next</b><ul>{theory.sectorOutlook.map((item,index)=><li key={`${item}-${index}`}>{item}</li>)}</ul></div></div>
 <div className="countercase"><p><b>COUNTERCASE</b> {theory.countercase}</p><p><b>KILL CONDITIONS / OBSERVABLE INVALIDATION</b> {theory.invalidation}</p>{theory.tripwire&&<p><b>TRIPWIRE GEOMETRY</b> {theory.tripwire.direction.toUpperCase()} thesis · creation quote {num(theory.tripwire.creationPrice)} · close {theory.tripwire.operator} {num(theory.tripwire.level)} · VALIDATED UNBREACHED AT CREATION</p>}<p><b>HORIZON</b> {theory.horizon}</p></div>
 {theory.sentimentEvidence.length?<div className="sentiment-evidence" aria-label="Alpha Vantage sentiment"><b className="mini-head">ALPHA VANTAGE SENTIMENT · ATTENTION / MOOD ONLY · ZERO SCORE WEIGHT</b>{theory.sentimentEvidence.map(item=><a key={item.id} href={item.url} target="_blank" rel="noreferrer"><div><span className={`status ${item.stance==="confirming"?"confirming":item.stance==="challenging"?"challenged":"neutral"}`}>{item.stance}</span><strong>{item.ticker} · {item.tickerLabel}</strong></div><h5>{item.title}</h5><p>Ticker score {num(item.tickerScore)} ({item.tickerLabel}) · overall score {num(item.overallScore)} ({item.overallLabel})</p><small>Published {new Date(item.publishedAt).toLocaleString()} · as of {new Date(item.asOf).toLocaleString()} · {item.publisher} via Alpha Vantage</small><span className="sentiment-url">{item.url}</span></a>)}</div>:<div className="notice">ALPHA VANTAGE SENTIMENT · NO_DATA. No snapshot at or under 48 hours old; missing sentiment is not scored.</div>}
 <div className="source-stack"><b className="mini-head">PRIMARY EVIDENCE LINKS · {theory.independentSourceCount} INDEPENDENT PUBLISHER{theory.independentSourceCount===1?"":"S"}</b>{theory.sources.map((source,index)=><a key={`${source.url}-${index}`} href={source.url} target="_blank" rel="noreferrer"><span>{source.source}</span><strong>{source.title}</strong><small>{source.publishedAt?`Published ${new Date(source.publishedAt).toLocaleString()}`:`Retrieved ${new Date(source.retrievedAt).toLocaleString()}`}</small>{source.snippet&&<p className="source-snippet">{source.snippet}</p>}</a>)}</div>
 <div className="social-evidence"><div className="section-head"><h3>Public social chatter · {theory.primarySymbol}</h3><a href="https://paste.trade" target="_blank" rel="noreferrer">PASTE.TRADE LEADERBOARD</a></div>{socialPending?<div className="empty">READING PUBLIC CHATTER…</div>:social?<><div className={`social-read ${social.theoryRead}`}><b>{social.theoryRead.toUpperCase()} THE THEORY</b><span>{social.theoryReadNote}</span></div><MetricGrid items={[{label:"Stocktwits bullish",value:social.stocktwits.bullishPct==null?"Unavailable":`${num(social.stocktwits.bullishPct)}%`,tone:(social.stocktwits.bullishPct??50)>=55?"pos":(social.stocktwits.bullishPct??50)<=45?"neg":""},{label:"Bullish / bearish",value:`${social.stocktwits.bullish} / ${social.stocktwits.bearish}`},{label:"Untagged",value:String(social.stocktwits.untagged)},{label:"Reddit discussions",value:social.reddit.status==="ok"?String(social.reddit.discussions):"Unavailable"}]}/><p className="subline">{social.note} {social.xTimelineState} Refreshed {new Date(social.fetchedAt).toLocaleString()}.</p><div className="social-calls">{social.messages.slice(0,6).map(message=><a key={message.id} href={message.sourceUrl??undefined} target={message.sourceUrl?"_blank":undefined} rel={message.sourceUrl?"noreferrer":undefined}><span><b>{message.source}</b>{message.handle?` · @${message.handle}`:""}</span><span className={message.sentiment==="bullish"?"pos":message.sentiment==="bearish"?"neg":""}>{message.sentiment.toUpperCase()}</span><p>{message.text}</p><small>{message.createdAt?new Date(message.createdAt).toLocaleString():"Time unavailable"}{message.engagement==null?"":` · ${message.engagement} likes`}</small></a>)}</div>{!social.messages.length&&<div className="empty">No public ticker discussions were returned.</div>}</>:<div className="empty">Public chatter unavailable for this theory.</div>}</div>
 </article>
}
function EventActionMap(){
 const [scenario,setScenario]=useState("");const map=useMutation({mutationFn:()=>api.mapEventAction({scenario:scenario.trim()})});
 return <div className="event-map"><div className="section-head"><h3>Event / action map</h3></div><form className="scenario-form" onSubmit={e=>{e.preventDefault();if(scenario.trim().length>=8)map.mutate()}}><label htmlFor="event-scenario">Scenario to map</label><div><input id="event-scenario" value={scenario} onChange={e=>setScenario(e.target.value)} placeholder="AI datacenters strain municipal water supply"/><button className="action" disabled={map.isPending||scenario.trim().length<8}>{map.isPending?"VERIFYING…":"MAP SCENARIO"}</button></div></form>{map.error&&<div className="error">Event map failed: {String(map.error)}</div>}{map.data&&<article className={`event-result ${map.data.status}`}><div className="theory-head"><div className="tag-row"><span className={`status ${map.data.status}`}>{map.data.status}</span><span className="badge">{map.data.weightedScore>=0?"+":""}{map.data.weightedScore} WEIGHTED</span>{map.data.directionalPick==="none"&&<span className="fork-label">NO DIRECTIONAL PICK</span>}</div><span>{map.data.confidenceTier.toUpperCase()} evidence · {map.data.supportLabel}</span></div>{map.data.fallback&&<div className="notice">{map.data.fallback}</div>}<div className="layer-grid">{map.data.layers.map(layer=><div className={`layer ${layer.verdict}`} key={layer.name}><div><b>{layer.name}</b><span>{layer.verdict} · w {layer.weight} · {layer.contribution>0?"+":""}{layer.contribution}</span></div>{layer.deduplicated&&<small className="dedup-note">{layer.deduplicationNote??"deduplicated (shared sources)"}</small>}<p>{layer.evidence}</p></div>)}</div><div className="theory-columns"><div><b className="mini-head">Verified premises</b>{map.data.verifiedPremises.length?<ul>{map.data.verifiedPremises.map((premise,index)=><li key={index}>{premise.statement} <small>[{premise.sourceIndexes.join(", ")}]</small></li>)}</ul>:<p className="subline">None verified.</p>}</div><div><b className="mini-head">Inference</b>{map.data.inferences.length?<ul>{map.data.inferences.map((item,index)=><li key={index}>{item}</li>)}</ul>:<p className="subline">No inference generated.</p>}</div></div><div className="action-chain">{map.data.legs.map((leg,index)=><div className={leg.check==="broken"?"broken-hop":""} key={index}><div className="hop-head"><span>{leg.kind}</span><span className={`status ${leg.check==="pass"?"confirming":"refuted"}`}>{leg.check}</span></div><b>{leg.from} → {leg.to}</b><p>{leg.mechanism}</p>{leg.kind==="verified"?<div className="hop-sources">{leg.evidence.map((source,i)=><a key={`${source.url}-${i}`} href={source.url} target="_blank" rel="noreferrer">{source.source} · {source.title}</a>)}</div>:<small className="subline">Inference — explicitly unverified.</small>}</div>)}</div><div className="countercase"><p><b>COUNTERCASE</b> {map.data.countercase}</p><p><b>OBSERVABLE INVALIDATION</b> {map.data.invalidation}</p></div><div className="source-stack">{map.data.sources.map((source,index)=><a key={`${source.url}-${index}`} href={source.url} target="_blank" rel="noreferrer">[{index+1}] {source.source} · {source.title}</a>)}</div></article>}</div>
}

function SmartMoney({a}:{a:Analysis}){const sym=a.instrument?.symbol??"";const ret=a.returns.find(r=>r.label==="30d")?.value??null;const q=useQuery({queryKey:["whales",sym],queryFn:()=>api.getWhaleData({ticker:sym,issuerName:a.instrument?.name??sym,marketCap:a.instrument?.marketCap??null,return30d:ret}),enabled:!!sym});return <>{<Section title="Institutional footprint proxies"><div className="list panel">{a.smartMoney.map(x=><div className="row" key={x.label}><div><h4>{x.label}</h4><p>{x.detail}</p></div><b className={`mono ${x.tone==="positive"?"pos":x.tone==="negative"?"neg":""}`}>{x.value}</b></div>)}</div></Section>}{q.isPending?<div className="loading">READING DISCLOSURES…</div>:q.error?<div className="error">EDGAR intelligence unavailable. Volume proxies above remain available.</div>:q.data&&<><div className="notice">{q.data.note}</div><Section title="Silent hints · early institutional footprints"><p className="subline">Evidence-linked footprints that can appear before a broad narrative. Confidence labels rank evidence quality, never probability.</p><div className="silent-hints">{q.data.silentHints.length?q.data.silentHints.map((hint,index)=><a className="silent-hint" key={`${hint.sourceUrl}-${index}`} href={hint.sourceUrl} target="_blank" rel="noreferrer"><div className="theory-head"><span className="badge">{hint.type.replaceAll("_"," ")}</span><span className={`confidence ${hint.confidence}`}>{hint.confidence.toUpperCase()}</span></div><h4>{hint.label}</h4><p>{hint.detail}</p><small>{hint.observedAt??"date unavailable"} · {hint.sourceTitle}</small></a>):<div className="empty">No evidence-backed early footprint was found in the current filings and source search.</div>}</div></Section><Section title="Marquee 13F holders · last reported quarter"><div className="list panel">{q.data.holdings.length?q.data.holdings.map(h=><div className="row" key={h.manager}><div><h4>{h.manager}</h4><p>{h.reportDate} · {h.change}{h.changePct!=null?` ${pct(h.changePct)}`:""} · {num(h.portfolioPct)}% portfolio</p>{h.flag&&<span className="whale-flag">{h.flag}</span>}</div><a href={h.sourceUrl} target="_blank" rel="noreferrer" className="mono">{money(h.value)}</a></div>):<div className="empty">No matching marquee-manager position was parsed.</div>}</div></Section><Section title="Form 4 insiders"><div className="list panel">{q.data.insiderCluster&&<div className="notice pos">INSIDER BUY CLUSTER DETECTED</div>}{q.data.insiders.length?q.data.insiders.map((x,i)=><div className="row" key={`${x.owner}-${i}`}><div><h4>{x.owner} · {x.title}</h4><p>{x.date} · {num(x.shares)} shares at {money(x.price)}</p></div><a href={x.sourceUrl} target="_blank" rel="noreferrer" className={x.type==="Buy"?"pos":"neg"}>{x.type}</a></div>):<div className="empty">No recent open-market Form 4 buys or sells parsed.</div>}</div></Section><Section title="Activist 13D / 13G"><div className="list panel">{q.data.activists.length?q.data.activists.map((x,i)=><div className="row" key={`${x.sourceUrl}-${i}`}><div><h4>{x.form} · {x.filer}</h4><p>Filed {x.filingDate} · event {x.reportDate} · {x.lagDays??"—"} day disclosure lag</p></div><a href={x.sourceUrl} target="_blank" rel="noreferrer">FILING</a></div>):<div className="empty">No recent issuer Schedule 13D/13G filing in the current submissions window.</div>}</div></Section><Section title="Congressional disclosure watch"><div className="list panel">{q.data.congressional.length?q.data.congressional.map(x=><div className="research-item" key={x.url}><a href={x.url} target="_blank" rel="noreferrer"><b>{x.title}</b></a><p className="subline">{x.source} · {x.publishedAt??"date unavailable"}</p></div>):<div className="empty">No ticker-specific disclosure results found.</div>}</div></Section><div className="notice">Institutional aggregate ownership %, FINRA short-interest ratios, and real fund flows require standardized datasets not consistently available through these free endpoints. This view does not invent them. Dark-pool and options-flow claims are intentionally excluded.</div></>}</>}
function _Rotation({choose}:{choose:(q:string)=>void}){const q=useQuery({queryKey:["rotation"],queryFn:()=>api.getRotation({}),staleTime:15*60*1000});if(q.isPending)return <LoadingSkeleton label="Loading cached rotation"/>;if(q.error)return <div className="error">Rotation failed: {String(q.error)}</div>;return <><Section title="Relative-strength breadth"><MetricGrid items={[{label:"Leading SPY · 30d",value:String(q.data.breadth.leading30d),tone:"pos"},{label:"Lagging SPY · 30d",value:String(q.data.breadth.lagging30d),tone:"neg"},{label:"Unavailable",value:String(q.data.breadth.unavailable)}]}/><div className="notice">{q.data.note}</div></Section><Section title="Watchlist rotation vs SPY"><div className="rotation-table" role="table" aria-label="Relative strength versus SPY"><div className="rotation-row rotation-head" role="row"><span>Instrument</span><span>30d ratio</span><span>90d ratio</span><span>Range</span></div>{q.data.rows.map((s)=><button className="rotation-row rotation-action" role="row" key={s.symbol} onClick={()=>choose(s.symbol)} disabled={!!s.error} aria-label={`Open ${s.symbol} dossier`}><span><b>{s.symbol}</b><small>{s.name}</small></span><span className={(s.ratio30d??0)>=0?"pos":"neg"}>{pct(s.ratio30d)}</span><span className={(s.ratio90d??0)>=0?"pos":"neg"}>{pct(s.ratio90d)}</span><span>{s.error?"Unavailable":`${s.rangeLabel} ›`}</span></button>)}</div><p className="subline">Tap a row to open its dossier · aligned daily closes · Yahoo Finance · calculated {new Date(q.data.asOf).toLocaleString()}</p></Section></>}
function PortfolioCorrelation(){const q=useQuery({queryKey:["portfolio-correlation"],queryFn:()=>api.getPortfolioCorrelation({}),staleTime:5*60*1000});return <Section title="Correlation check · one bet, not eight">{q.isPending?<LoadingSkeleton label="Aligning cached return histories"/>:q.error?<div className="error">Correlation check failed: {String(q.error)}</div>:q.data?.status==="unavailable"?<div className="empty">{q.data.warning}<small>{q.data.missingSymbols.length?` Missing cache: ${q.data.missingSymbols.join(", ")}`:""}</small></div>:q.data&&<><div className={q.data.warning.startsWith("No broad")?"notice":"daily-stop"}>{q.data.warning}</div><div className="correlation-grid">{q.data.pairs.slice(0,12).map(row=><div key={`${row.a}-${row.b}`}><b>{row.a} / {row.b}</b><strong className={Math.abs(row.correlation)>=.75?"neg":""}>{num(row.correlation,3)}</strong></div>)}</div><p className="subline">{q.data.method} · {q.data.sessions} aligned sessions · {q.data.symbols.length} instruments{q.data.missingSymbols.length?` · cache unavailable for ${q.data.missingSymbols.join(", ")}`:""}</p></>}</Section>}
function Journal({symbol,qc,choose}:{symbol:string;qc:ReturnType<typeof useQueryClient>;choose:(q:string)=>void}){const q=useQuery({queryKey:["trades"],queryFn:()=>api.listTrades({})});const analytics=useQuery({queryKey:["journal-analytics"],queryFn:()=>api.getJournalAnalytics({})});const [editing,setEditing]=useState<number|null>(null);const [form,setForm]=useState({ticker:symbol,direction:"long" as "long"|"short",setup:"Trend",entry:"",exitPrice:"",size:"",thesis:"",rMultiple:"",notes:"",tradeDate:new Date().toISOString().slice(0,10)});const save=useMutation({mutationFn:()=>{const data={ticker:form.ticker.toUpperCase(),direction:form.direction,setup:form.setup,entry:Number(form.entry),exitPrice:form.exitPrice?Number(form.exitPrice):null,size:Number(form.size),thesis:form.thesis,rMultiple:form.rMultiple?Number(form.rMultiple):null,notes:form.notes,tradeDate:form.tradeDate};return editing?api.updateTrade({...data,id:editing}):api.saveTrade(data)},onSuccess:()=>{qc.invalidateQueries({queryKey:["trades"]});qc.invalidateQueries({queryKey:["journal-analytics"]});setEditing(null);setForm({...form,entry:"",exitPrice:"",size:"",thesis:"",rMultiple:"",notes:""})}});const del=useMutation({mutationFn:(id:number)=>api.deleteTrade({id}),onSuccess:()=>{qc.invalidateQueries({queryKey:["trades"]});qc.invalidateQueries({queryKey:["journal-analytics"]})}});return <>
 <Section title="Journal analytics"><div className="notice"><b>R accounting:</b> {analytics.data?.rDefinition??"R definition unavailable."}</div><MetricGrid items={[{label:"Expectancy · headline",value:analytics.data?.expectancy==null?"—":`${num(analytics.data.expectancy)}R / trade`,tone:(analytics.data?.expectancy??0)>=0?"pos":"neg"},{label:"Average win",value:analytics.data?.avgWin==null?"—":`${num(analytics.data.avgWin)}R`},{label:"Average loss",value:analytics.data?.avgLoss==null?"—":`${num(analytics.data.avgLoss)}R`,tone:"neg"},{label:"Win rate · secondary",value:pct(analytics.data?.winRate)},{label:"Closed trades",value:String(analytics.data?.closed??0)},{label:"Average R",value:analytics.data?.avgR==null?"—":`${num(analytics.data.avgR)}R`,tone:(analytics.data?.avgR??0)>=0?"pos":"neg"}]}/>{analytics.data?.groups.length?<div className="list panel">{analytics.data.groups.map(x=><div className={`row ${x.killSuggested?"kill-row":""}`} key={x.label}><div><h4>{x.label}</h4><p>{x.trades} closed trades · {num(x.winRate)}% hit rate</p></div><div><b className={x.expectancy>=0?"pos":"neg"}>{num(x.expectancy)}R expectancy</b>{x.killSuggested&&<small className="kill-copy">SIZE DOWN / KILL</small>}</div></div>)}</div>:<div className="notice">Add R multiples to closed trades to build personalized setup statistics. After 3 comparable trades, those results annotate future factor-agreement reads.</div>}</Section><Section title="Open-portfolio factor exposure"><MetricGrid items={[{label:"Open positions",value:String(analytics.data?.portfolio.openPositions??0)},{label:"Gross notional",value:money(analytics.data?.portfolio.grossNotional)},{label:"Net notional",value:money(analytics.data?.portfolio.netNotional),tone:(analytics.data?.portfolio.netNotional??0)>=0?"pos":"neg"},{label:"Long / short",value:`${money(analytics.data?.portfolio.longNotional)} / ${money(analytics.data?.portfolio.shortNotional)}`}]}/>{analytics.data?.exposures.length?<div className="exposure-list">{analytics.data.exposures.map(x=><div key={x.factor}><div><b>{x.factor}</b><small>{x.positions} open · gross {money(x.grossNotional)}</small></div><strong className={x.netNotional>=0?"pos":"neg"}>{x.netNotional>=0?"NET LONG":"NET SHORT"} {money(Math.abs(x.netNotional))}</strong></div>)}</div>:<div className="empty">Log open trades to see net setup-factor exposure. This view uses journal positions only.</div>}</Section><PortfolioCorrelation/>
 <Section title={editing?"Edit trade":"Log trade"}><form className="form panel" onSubmit={e=>{e.preventDefault();save.mutate()}}><div className="form-grid">{[["Ticker","ticker","text"],["Entry","entry","number"],["Exit","exitPrice","number"],["Size","size","number"],["Realized R multiple · user entered","rMultiple","number"],["Date","tradeDate","date"]].map(([l,k,t])=><div className="field" key={k}><label htmlFor={`j-${k}`}>{l}</label><input id={`j-${k}`} type={t} step="any" value={form[k as keyof typeof form]} onChange={e=>{if(k)setForm({...form,[k]:e.target.value})}}/></div>)}<div className="field"><label htmlFor="j-dir">Direction</label><select id="j-dir" value={form.direction} onChange={e=>setForm({...form,direction:e.target.value as "long"|"short"})}><option value="long">Long</option><option value="short">Short</option></select></div><div className="field"><label htmlFor="j-setup">Setup</label><select id="j-setup" value={form.setup} onChange={e=>setForm({...form,setup:e.target.value})}>{["Trend","Breakout","Reversal","Event","Other","Unspecified"].map(x=><option key={x}>{x}</option>)}</select></div></div><div className="field"><label htmlFor="j-thesis">Thesis</label><textarea id="j-thesis" required value={form.thesis} onChange={e=>setForm({...form,thesis:e.target.value})}/></div><div className="field"><label htmlFor="j-notes">Notes</label><textarea id="j-notes" value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></div><button className="action">{editing?"UPDATE TRADE":"SAVE TRADE"}</button></form></Section><Section title="Journal"><div className="list panel">{q.data?.trades.length?q.data.trades.map(t=><div className="row" key={t.id}><button className="row-link" onClick={()=>choose(t.ticker)} aria-label={`Open ${t.ticker} dossier from journal`}><h4>{t.ticker} · {t.direction.toUpperCase()} · {t.setup}</h4><p>{t.tradeDate} · {money(t.entry)} → {money(t.exitPrice)} · {num(t.size)} shares · {t.rMultiple==null?"open":`${num(t.rMultiple)}R`}</p><p>{t.thesis}</p><small className="subline">OPEN DOSSIER</small></button><div><button className="secondary" onClick={()=>{setEditing(t.id);setForm({ticker:t.ticker,direction:t.direction,setup:t.setup,entry:String(t.entry),exitPrice:t.exitPrice==null?"":String(t.exitPrice),size:String(t.size),thesis:t.thesis,rMultiple:t.rMultiple==null?"":String(t.rMultiple),notes:t.notes,tradeDate:t.tradeDate})}}>EDIT</button><button className="secondary danger" onClick={()=>del.mutate(t.id)}>DELETE</button></div></div>):<div className="empty">No trades logged yet.</div>}</div></Section></>}
function Sizing({symbol,price,invalidation,volatility}:{symbol:string;price:number;invalidation:number;volatility:string}){const [v,setV]=useState({account:"10000",risk:"1",bps:"12",notional:"5000",entry:price?String(price):"",stop:invalidation?String(invalidation):"",target:price&&invalidation?String(price+Math.abs(price-invalidation)*5):"",dailyLimit:"2",side:"long" as "long"|"short"});const tracker=useQuery({queryKey:["tracker"],queryFn:()=>api.getSignalTracker({})});const analytics=useQuery({queryKey:["journal-analytics"],queryFn:()=>api.getJournalAnalytics({})});const account=Number(v.account)||0,riskPct=Number(v.risk)||0,bps=Number(v.bps)||0,notional=Number(v.notional)||0,entry=Number(v.entry)||0,stop=Number(v.stop)||0,target=Number(v.target)||0,dailyLimit=Math.abs(Number(v.dailyLimit)||2),d=Math.abs(entry-stop),reward=Math.abs(target-entry),rewardRisk=d>0?reward/d:0,riskBudget=account*riskPct/100,friction=notional*bps/10000,frictionPerShare=entry*bps/10000,riskShares=d+frictionPerShare>0?Math.floor(riskBudget/(d+frictionPerShare)):0,referenceShares=entry>0?Math.floor(notional/entry):0,frictionRatio=riskBudget>0?friction/riskBudget*100:null;const statRows=tracker.data?.stats??[],sampleCount=statRows.reduce((sum,row)=>sum+row.samples,0),measuredExpectancy=sampleCount?statRows.reduce((sum,row)=>sum+row.expectancy*row.samples,0)/sampleCount:null,highVol=/high|elevated|extreme/i.test(volatility),rawTier=measuredExpectancy==null?1:measuredExpectancy<=0?0:measuredExpectancy<1?1:measuredExpectancy<3?2:3,tier=rewardRisk<5?0:Math.max(1,rawTier-(highVol?1:0)),rung=tier===0?"NO POSITION / KILL":tier===1?"PROBE":tier===2?"HALF-SIZE":"FULL-SIZE",recommendedRisk=tier===0?0:tier===1?Math.min(riskPct,.25):tier===2?Math.min(riskPct,.5):riskPct,todayR=analytics.data?.todayR??0,lossLimitHit=todayR<=-dailyLimit;const timing=useMutation({mutationFn:()=>api.checkEntry({symbol,direction:v.side,entryPrice:entry,invalidationLevel:stop,targetLevel:target})});return <><Section title="Entry timing check"><div className="form panel"><div className="sizing-context"><b>{symbol}</b><span>Fuse quote distance, RSI/ATR, volume, open signals, event proximity and a hard 5:1 payoff gate.</span></div><div className="form-grid"><div className="field"><label htmlFor="timing-side">Direction</label><select id="timing-side" value={v.side} onChange={e=>setV({...v,side:e.target.value as "long"|"short"})}><option value="long">Long</option><option value="short">Short</option></select></div>{[["Planned entry","entry"],["Invalidation level (trade plan)","stop"],["Planned target (trade plan)","target"]].map(([l,k])=><div className="field" key={k}><label htmlFor={`timing-${k}`}>{l}</label><input id={`timing-${k}`} type="number" step="any" min="0" value={v[k as "entry"|"stop"|"target"]} onChange={e=>setV({...v,[String(k)]:e.target.value})}/></div>)}</div><div className={`rr-gate ${rewardRisk>=5?"pass":"fail"}`}><b>{num(rewardRisk)}:1 REWARD / RISK</b><span>{rewardRisk>=5?"ASYMMETRIC PAYOFF GATE PASSED":"HARD 5:1 GATE FAILED"}</span></div><button className="action" onClick={()=>timing.mutate()} disabled={!symbol||entry<=0||stop<=0||target<=0||timing.isPending}>{timing.isPending?"CHECKING PRICE + EVENTS…":"CHECK ENTRY TIMING"}</button></div>{timing.error&&<div className="error">Timing check failed: {String(timing.error)}</div>}{timing.data&&<article className={`timing-result ${timing.data.verdict}`}><div className="timing-verdict"><span>{timing.data.verdict.toUpperCase()}</span><div><h4>{timing.data.headline}</h4><p>{timing.data.symbol} · {timing.data.direction.toUpperCase()} · planned {money(timing.data.plannedEntry)} · current {money(timing.data.currentPrice)}</p><strong className={timing.data.asymmetricPayoff?"pos":"neg"}>{num(timing.data.rewardRisk)}:1 · {timing.data.asymmetricPayoff?"DEFINED-RISK ASYMMETRY":"5:1 GATE FAILED"}</strong></div></div><div className="timing-checks">{timing.data.checks.map((check,index)=><div key={`${check.category}-${index}`}><span className={`status ${check.status==="supports"?"confirming":check.status==="conflicts"?"refuted":"challenged"}`}>{check.status}</span><b>{check.category}</b><strong>{check.value}</strong><p>{check.detail}</p>{check.sourceUrl&&<a href={check.sourceUrl} target="_blank" rel="noreferrer">SOURCE</a>}</div>)}</div><p className="notice">{timing.data.disclaimer}</p></article>}</Section><Section title="Expectancy-tiered sizing"><div className={`expectancy-tier ${tier===0?"kill-flag":""}`}><div><span className="eyebrow">MEASURED OUTCOMES · 5:1 GATE · {volatility.toUpperCase()} VOLATILITY</span><strong>{rung}</strong><p>{measuredExpectancy==null?"UNCALIBRATED — no closed tracker outcomes. Maximum rung is probe.":`${pct(measuredExpectancy)} measured expectancy per signal across ${sampleCount} closed outcomes. ${highVol?"Elevated volatility reduces the sizing rung by one.":"Current volatility does not reduce the expectancy rung."}`} {rewardRisk<5?"The 5:1 gate fails, so size is zero.":`Suggested risk cap: ${num(recommendedRisk)}% of account.`}</p></div><div className="field"><label htmlFor="daily-limit">Daily loss limit · R</label><input id="daily-limit" type="number" min="0.1" step="0.1" value={v.dailyLimit} onChange={e=>setV({...v,dailyLimit:e.target.value})}/></div></div>{lossLimitHit&&<div className="daily-stop">FLAT BY NOW · today's closed journal result is {num(todayR)}R, beyond the −{num(dailyLimit)}R loss limit.</div>}</Section><Section title="Risk-capture calculator"><div className="form panel"><div className="sizing-context"><b>{symbol}</b><span>Reference price {money(price)}</span></div><div className="form-grid">{[["Account size","account"],["Risk per idea %","risk"],["Round-trip fees + slippage · bps","bps"],["Reference notional","notional"],["Planned entry","entry"],["Invalidation level (trade plan)","stop"],["Planned target (trade plan)","target"]].map(([l,k])=><div className="field" key={k}><label htmlFor={`s-${k}`}>{l}</label><input id={`s-${k}`} type="number" step="any" value={v[k as keyof typeof v]} onChange={e=>{if(k)setV({...v,[String(k)]:e.target.value})}}/></div>)}<div className="field"><label htmlFor="s-side">Side</label><select id="s-side" value={v.side} onChange={e=>setV({...v,side:e.target.value as "long"|"short"})}><option value="long">Long</option><option value="short">Short</option></select></div></div></div></Section><Section title="Mechanical output"><MetricGrid items={[{label:"Expectancy sizing rung",value:rung,tone:tier===0?"neg":"pos"},{label:"Measured expectancy",value:measuredExpectancy==null?"UNCALIBRATED":`${pct(measuredExpectancy)} / signal`,tone:(measuredExpectancy??0)>0?"pos":"neg"},{label:"Suggested account risk",value:`${num(recommendedRisk)}%`},{label:"Risk budget",value:money(riskBudget)},{label:"Stop distance / share",value:money(d)},{label:"Risk-sized shares",value:num(riskShares,0)},{label:"Reference shares",value:num(referenceShares,0)},{label:"Estimated friction",value:money(friction)},{label:"Friction / risk",value:frictionRatio==null?"—":`${num(frictionRatio)}%`},{label:"DEFINED TARGET (5R PAYOFF)",value:money(target)},{label:"Reward / risk",value:`${num(rewardRisk)}:1`,tone:rewardRisk>=5?"pos":"neg"}]}/><div className="notice">Sizing uses closed tracker outcomes, the hard 5:1 gate, and the displayed volatility regime. It returns zero when expectancy is negative or the payoff gate fails. Fee and slippage inputs are assumptions; nothing here predicts execution quality or fill price.</div></Section></>}
function Rules({qc}:{qc:ReturnType<typeof useQueryClient>}){const q=useQuery({queryKey:["rules"],queryFn:()=>api.listRules({})});const [text,setText]=useState("");const add=useMutation({mutationFn:()=>api.saveRule({text}),onSuccess:()=>{setText("");qc.invalidateQueries({queryKey:["rules"]})}});const upd=useMutation({mutationFn:(x:{id:number;text:string;checked:boolean})=>api.updateRule(x),onSuccess:()=>qc.invalidateQueries({queryKey:["rules"]})});const del=useMutation({mutationFn:(id:number)=>api.deleteRule({id}),onSuccess:()=>qc.invalidateQueries({queryKey:["rules"]})});return <><Section title="Add trading rule"><form className="searchrow" onSubmit={e=>{e.preventDefault();if(text.trim())add.mutate()}}><input aria-label="New trading rule" value={text} onChange={e=>setText(e.target.value)} placeholder="e.g. Never average down without a new thesis"/><button>ADD</button></form></Section><Section title="Checklist"><div className="list panel">{q.data?.rules.length?q.data.rules.map(r=><div className="row" key={r.id}><label style={{display:"flex",gap:10,alignItems:"flex-start"}}><input type="checkbox" checked={r.checked} onChange={()=>upd.mutate({id:r.id,text:r.text,checked:!r.checked})}/><span style={{textDecoration:r.checked?"line-through":"none"}}>{r.text}</span></label><button className="secondary danger" onClick={()=>del.mutate(r.id)}>DELETE</button></div>):<div className="empty">No rules yet. Add only the rules you choose.</div>}</div></Section></>}
function Research({a}:{a:Analysis}){const i=a.instrument!;const q=useQuery({queryKey:["research",i.symbol],queryFn:()=>api.getResearch({symbol:i.symbol,name:i.name})});const values=useMemo(()=>a.indicators.map(x=>`${x.label}: ${num(x.value)}${x.unit?` ${x.unit}`:""}`).join(" · "),[a.indicators]);return <><Section title="Quant brief"><div className="panel"><p className="prose">{a.thesis}</p><p className="subline">{values}</p><p className="subline">Value and quality fundamentals are not supplied structurally by the free market feed, so they are not scored here.</p></div></Section><Section title="SEC filings · recent"><div className="list panel">{a.secFilings.items.length?a.secFilings.items.map(f=><div className="research-item" key={f.accession}><a href={f.url} target="_blank" rel="noreferrer"><b>{f.form} · filed {f.filedDate}</b></a><p className="subline">{f.source} · accession {f.accession}{f.acceptedDate?` · accepted ${f.acceptedDate}`:""}{a.secFilings.asOf?` · snapshot as of ${a.secFilings.asOf}`:""}</p></div>):<div className="empty">{a.secFilings.note}</div>}</div></Section><Section title="Earnings calendar"><div className="list panel">{a.earningsCalendar.events.length?a.earningsCalendar.events.map((event,index)=><div className="research-item" key={`${event.symbol}-${event.date}-${index}`}><b>{event.symbol} · {event.date}</b><p className="subline">{event.source} · snapshot as of {a.earningsCalendar.asOf}{event.quarter!=null?` · quarter ${num(event.quarter)}`:""}</p><p>{event.epsEstimate!=null?`EPS estimate ${num(event.epsEstimate)}`:"EPS estimate unavailable"}{event.epsActual!=null?` · actual ${num(event.epsActual)}`:""}{event.revenueEstimate!=null?` · revenue estimate ${num(event.revenueEstimate)}`:""}{event.revenueActual!=null?` · actual ${num(event.revenueActual)}`:""}</p></div>):<div className="empty">{a.earningsCalendar.note}</div>}</div></Section><Section title="Current news + filing coverage"><div className="list panel">{q.isPending?<div className="empty">SEARCHING…</div>:q.data?.results.map(x=><div className="research-item" key={x.url}><a href={x.url} target="_blank" rel="noreferrer"><b>{x.title}</b></a><p className="subline">{x.source} · {x.publishedAt??"date unavailable"}</p><p>{x.snippet}</p></div>)}</div></Section><Section title="Market sources"><div className="list sources">{i.sources.map(s=><a key={s.url} href={s.url} target="_blank" rel="noreferrer">{s.title}</a>)}</div></Section></>}

